import { Verse } from '@/types';

export const chapter14Verses: Verse[] = [
  { id: 448, chapterId: 14, order: 1, original: "宪问耻，子曰：“邦有道，谷；邦无道，谷，耻也。”“克、伐、怨、欲不行焉，可以为仁矣？”子曰：“可以为难矣，仁则吾不知也。”", translation: "原宪问什么叫耻辱。孔子说：“国家政治清明，做官领俸禄；国家政治黑暗，也做官领俸禄，这就是耻辱。”原宪又问：“好胜、自夸、怨恨和贪婪这四种毛病都没有，可以称得上仁吗？”孔子说：“可以说是难能可贵，至于是否是仁，我就不能断定了。”", commentary: "①宪：原宪，孔子弟子，清净守节、贫而乐道，本篇以他发问而得名。\\n②耻：耻辱、羞愧。\\n③谷：俸禄，此处用作动词，指做官领取俸禄。\\n④克：好胜，总想胜过别人。\\n⑤伐：自夸、炫耀，自以为了不起。\\n⑥怨：怨恨，怨天尤人。\\n⑦欲：贪婪、贪欲。\\n⑧不行焉：不表现出来，指好胜、自夸、怨恨、贪欲不以言语或行为显露，未必内心全无。\\n⑨难：难能可贵。\\n---\\n\\n【解读】本章为《宪问》篇首章。原宪问耻，孔子答以“邦有道，谷；邦无道，谷，耻也”，并回应原宪关于“克、伐、怨、欲不行焉”能否算仁的疑问。宪问即原宪，孔子弟子，有颜渊身上清净守节、贫而乐道的品质。孔子为司寇时，原宪为其家宰，孔子予之高俸禄，原宪辞而不受，经孔子劝说方收下，用以分赠宗族亲友。《史记》载孔子卒后原宪隐居卫地，居室破败；子贡结驷连骑前往探望，见他衣冠敝旧，问“先生病乎”，原宪答以君子不能行道方是病，自己不过是贫，子贡终身以此为愧。\\n\\n“谷”即俸禄，此句向有两种理解：一说邦有道时君子可退隐，食禄亦可耻，然此解稍偏激；更通行的解释是，邦有道政治清平，有才干者当仁不让，出仕以领导人民；若邦无道仍食俸禄，便是参与乱政而无能拨乱反正，故为可耻。这与《泰伯》篇“天下有道则见，无道则隐；邦有道，贫且贱焉，耻也；邦无道，富且贵焉，耻也”完全一致，孔子盖以此激励原宪出而用世。\\n\\n原宪继而问：好胜、自夸、怨恨、贪欲都不表现出来，可谓仁乎？孔子答“可以为难矣，仁则吾不知也”，既许其难能可贵，又不以仁相许。其原因有二：其一，“不行”只是不显露于言行，未必内心无此念头，且后天强压终非仁者自然之态；其二，仁者当“己欲立而立人，己欲达而达人”，原宪偏于恬退自修，若该出仕而不出，亦失仁道，故孔子以“克己复礼”为仁，非一人独善所能成。人天生禀性难改，子路进取而原宪恬退，二者合一乃为仁。修身既当自守，亦须当仁不让，方能成其仁德。", keyPoint: "为政、仁德、修身、学习、教育、礼乐" },
  { id: 449, chapterId: 14, order: 2, original: "子曰：“士而怀居，不足以为士矣。”", translation: "孔子说：“士人如果留恋安逸的生活，就不足以做士人了。”", commentary: "①士：读书人、士人，有道德追求的君子。\\n②怀：思念、留恋，引申为挂怀于心。\\n③居：居处、安逸的生活；一说指停息、止步不前。\\n④足：够得上、配得上。\\n---\\n\\n【解读】本章紧承上章原宪问耻而来。孔子言“士而怀居，不足以为士矣”，既是批评留恋安逸的读书人，亦是赞许原宪恬退无私之品质——真正的士不当以自身安居为念，而当关心天下人之安居。\\n\\n“怀”即思念、留恋：没有时想念欲得，有了又怕失去。“居”有二解：一为居所与安逸的生活，一为止步停息。无论何解，士若自觉己身生活已足、学问已够，便不再配称士。盖士之志不在自谋福利，而在为大众谋福利，故永无休止之时。孔子自道“发愤忘食，乐以忘忧，不知老之将至”，终身奋斗，从无“学够了”之想；佛家所谓精进、永不舍多闻，与此同理。\\n\\n就形而上言，士若想止步不前、自认已成就，便永远达不到至高的道德境界；就形而下言，士若终日图谋大屋良田、贪图一己安逸，便放弃了对道德修养与影响他人之追求。然隐士虽避世而居，并非自图安逸——他们居陋处而惠及一方贫苦百姓，只因邦无道不能食禄，故避世以全道，并非不食俸禄、不谋善事。\\n\\n“怀”字之意，可参《里仁》篇“君子怀德，小人怀土”：君子不以居处为念；亦如“士志于道，而耻恶衣恶食者，未足与议也”。孔子又引《左传》重耳事为证：重耳流亡至齐，置房买地娶妾而不肯行，其妻劝以“心怀安乐，不能成大事”，重耳遂复上路，终返国即位为晋文公。《圣经》中耶稣亦言“狐狸有洞，鸟儿有窝，人子却没有枕头的地方”，喻学道者须能舍弃安逸。\\n\\n对今人而言，并非要求人人舍弃房屋、隐入深山，而是有而不以此挂怀，无而不以此为念；心思若尽在生活安逸上，便不易学习进步。心有更高之精神追求，方不负“士”之称。", keyPoint: "忧乐、教育" },
  { id: 450, chapterId: 14, order: 3, original: "子曰：“邦有道，危言危行；邦无道，危行言孙。”", translation: "孔子说：“国家政治清明，言语正直，行为正直；国家政治黑暗，行为也要正直，但言语应谦逊谨慎。”", commentary: "①邦：国、国家。邦有道指政治清明之时，邦无道指政治黑暗之时。\\n②危言危行：言语正直、行为正直。危字有多重相通之义——一是正，如\"正襟危坐\"之正；二是高，山高峻而直，直与高相连；三是独，不管他人如何，我自守此道；四是险，既高既直而与众不同，不能持守正道则易坠落，故\"危险\"同为一词。\\n③言孙：孙通\"逊\"，谦逊、谦顺。邦无道时，行为仍当正直，言语则可谦顺收敛，不唱高调。\\n④本章与公冶长第五论南容\"邦有道不废，邦无道免于刑戮\"、宁武子\"邦有道则智，邦无道则愚\"等章义理相通，可互相参看。\\n---\\n\\n【解读】本章讲君子在不同社会环境下应采用何种言行方式，核心在\"危\"字的深义。危言危行之\"危\"，既指正（正襟危坐之正），亦指高（山之高峻，高而自直，直与高相通），又指独（不管他人如何，我自守正道），更连着险——既高既直而与众不同，若不能持守正道便易跌落，故\"危险\"一词由此而来。诸多解释实则相通，如李白《蜀道难》\"危乎高哉\"之危，即是高、正、险诸义兼具。\\n\\n邦有道时，君子当危言危行，以正直高峻独特的言行引领世人、垂范天下，先觉觉后觉，使正道为众人所知，方是真正的邦有道。此时与第一章答原宪\"邦有道，谷\"相承：有道则出仕任事，以身作则。而邦无道时，危行不可变——行为任何时候都须正直；言则可谦逊收敛，不唱高调、不与世俗无道对抗。这有两层用意：从浅处看是自保，非教人说谎，只是不张扬、不对抗，以免危及生命；从深处看，谦逊的言辞与正直的行为本身就是一种引导，使人看到有道之士不浮夸、很谦逊，纷纷归附，渐可扭转无道之局。\\n\\n对话以史例印证：岳飞在邦无道时仍危言危行，高呼\"直捣黄龙，迎回二圣\"，触犯君主忌讳，终以生命为代价而大业未成；五代冯道则危行言孙，行为极为正直，收还掳掠女子、教子爱护生命，言辞谦虚不说大话，出使契丹以谦卑正行全身而还，并以三十三年之力将儒家九经刻版存世，使经典历经战乱而传，宋代理学之盛实有其功。史家批评冯道一臣不事二主、向外邦称臣，而苏轼、王安石则赞为大菩萨。此正见\"义\"之难知：君子的行为依于义，一般人往往不能深察。本章与南容\"邦有道不废，邦无道免于刑戮\"、宁武子\"邦有道则智，邦无道则愚\"、孔子\"危邦不入，乱邦不居\"等说一脉相承，共同揭示君子与时俯仰而守正不移的处世智慧。", keyPoint: "处世、学习、教育" },
  { id: 451, chapterId: 14, order: 4, original: "子曰：“有德者必有言，有言者不必有德。仁者必有勇，勇者不必有仁。”", translation: "孔子说：“有德的人一定有好的言论，但有好言论的人不一定有德。仁人一定勇敢，但勇敢的人不一定有仁德。”", commentary: "①言：此处指名言、善言。言为心声，有德者心中有道有德，其言必然中听、可传后世。\\n②德：道德、德行。有德之人言行一致，言必体现其德。\\n③仁：仁德，爱人爱己，儒家核心德目，义、礼诸德皆由仁衍生。\\n④勇：勇敢。仁、智、勇为三达德，归根结底系于仁；依于仁之勇方为大勇。\\n---\\n\\n【解读】本章揭示有德与有言、仁与勇之间的关系，其特点在于都是\"充分不必要\"的条件。有德者必有言，因为言为心声——心中有道有德，所说之理自然中听、可以流传千古。三皇五帝、神农《百草经》、黄帝《灵枢》《素问》，皆是德者之言的典范；老子本不欲著书，被关令尹喜拦下而出《道德经》五千言，即便不著书，孔子向老子问道时，名言亦已相授。可见《论语》之根其实亦在老子处，老子汇集商周巅峰文化，其源又可溯至此前两千余年的华夏积累。\\n\\n然而有言者不必有德：名言可以是内生的，也可以是学来的，能言善辩之人未必有道德。故此看人不能因言立人、以表象定贤否，须察其实质，看其有无德行。德必有行迹可验，言行一致方为君子，行不顾言、言不顾行皆非君子之道。\\n\\n下半章辨仁与勇之关系更为微细。仁、智、勇为三达德，归根结底系于仁。道、德、仁、义、礼五者本为一体，自上而下逐渐分化——失道而后德，失德而后仁；仁是爱人爱己，凡事适宜即为义，由义而生勇，故敢为天下先，纵众人皆反对，只要自认为合于道便坚持不改。所以仁者必有勇。而勇者不必有仁：出自一朝之忿的勇未必依于仁，虽不见得是坏事，却非最高级的大勇。荀子于此发挥最多，其《性恶篇》言\"仁之所在，无贫穷。仁之所亡，无富贵\"，又言\"天下知之，则欲与天下同苦之；天下不知之，则傀然独立天地之间而不畏，是上勇也\"——以仁为据、同甘共苦或独立无畏，方是最大的勇敢。\\n\\n本章对今人的启发，一在分辨德与言、仁与勇本非一事而又有相近处，不能以言取人、以勇论德；二在反观自身——有言时是否真有德行相随，故当敏于行而讷于言，所言方有分量，如\"夫人不言，言必有中\"；有仁心时是否真有勇气相伴，若无勇之仁便是小仁假仁，这正是伪君子之由来。孟子由义字发挥，荀子进而强调法、刑，皆因世道浇漓，人心不听德者之言而多从巧言令色之佞言。今人更须警醒，修身依据有德之言，行勇须自仁心出发。", keyPoint: "仁德、教育、言行" },
  { id: 452, chapterId: 14, order: 5, original: "南宫适问于孔子曰：“羿善射，奡荡舟，俱不得其死然；禹、稷躬稼而有天下。”夫子不答。南宫适出，子曰：“君子哉若人！尚德哉若人！”", translation: "南宫适向孔子问道：“羿擅长射箭，奡善于水战，都没有得到善终。禹和稷亲自耕作庄稼，却得到了天下。”孔子没有回答。南宫适退出去后，孔子说：“这个人是君子啊！这个人崇尚道德啊！”", commentary: "①羿：夏朝太康至少康时期有名的勇士。史书载有三羿：帝喾时教射的射官、传说中射落九日的神射手，以及有穷氏之君——他驱逐或杀害太康，占据夏都统治夏民，后为臣子寒浞所害。\\n②奡（ào）：寒浞之子，以勇力著称。荡舟有多种解释：或谓驾船状战车于陆地冲杀，或谓能两手把船从河中拖上岸，或谓擅长水战、驾舟冲锋。后为少康复国时所杀。\\n③躬稼：亲身耕种。可解作大禹亲自治水干活、后稷亲自种庄稼，二人皆与尧舜同时辅佐的圣人。\\n④南宫适：适读作\"扩\"，即南容。公冶长第五中孔子赞他\"邦有道不废，邦无道免于刑戮\"，并以其兄之女嫁之；又有\"三复白圭\"之勤于自省。\\n⑤稷：尧时掌管粮食之官，即后世的稷神，与\"社\"合称\"社稷\"；传为周人祖先，其子孙后代建立周朝，享八百年天下。\\n---\\n\\n【解读】本章在文理上是上一章\"仁者必有勇，勇者不必有仁\"的具体发挥：羿、奡恃勇力而得恶死，禹、稷躬稼而有天下，勇不足恃，德方可兴。要读懂此章，须明白南宫适为何发问、孔子为何如此回答。\\n\\n南宫适即南容，贵族出身，熟悉这些距春秋已千余年（相当于唐至今）的往事。他以夏朝史事设问：勇力过人的羿、奡皆不得好死，而亲自种庄稼的禹、稷反而得到天下。表面是在印证\"尚德不尚力\"，深一层却是以隐晦方式问孔子：当今世道的当权者多如羿、奡一般好勇力、耽逸乐，终将失国而不得其死；而先生领着我们亲身学习圣贤之道，虽非躬稼，将来是否也能有天下？南宫适深知邦无道则隐、邦有道则进之理，此问正见其志趣所在。\\n\\n孔子没有回答，实有深意：当着众多弟子，又因有姻亲之故，不便当面称赞；而不答即是默许、认可。南容亦不再追问，彼此心照，这个不回答本身就是回答。孔子又恐身边同学乃至后世之人不解其意，故待南容出去后补一句：\"君子哉若人！尚德哉若人！\"——他崇尚道德，所以是君子；他是君子，所以崇尚道德，二者相因。南宫适虽于史无多建树，但从此问可见其见地极高，只因身处孔子学说不得大行之时，遂如原宪一般隐居，仍如公冶长那样不断传习、教育，使圣人的所行所思所求广布后世，文化之根不绝。\\n\\n本章对今人的启示在于：崇尚道德即可成为君子，当以南容为榜样，重德而不恃力，勤于自省修养，并使圣贤之道代代相传。", keyPoint: "为政、仁德、教育" },
  { id: 453, chapterId: 14, order: 6, original: "子曰：“君子而不仁者有矣夫，未有小人而仁者也。”", translation: "孔子说：“君子之中也许有不仁的人吧，但小人之中却不会有仁人。”", commentary: "①君子：在此非指阶级身份，而是文质彬彬、既有文化修养又有厚实品德、为众人认可之人。\\n②仁：儒家最高的道德体现。孔子对仁者标准极高，颜回亦仅\"三月不违仁\"。\\n③小人：道德修养差、先天自私自利未受教化之人。《易经》所谓\"小人不耻不仁，不畏不义，不见利不劝\"。\\n④志于仁：以仁为志向。苟能志于仁，即非小人，所谓\"苟志于仁矣，无恶也\"。\\n---\\n\\n【解读】本章与前后章血脉相连，强调的是仁德极其难得。君子之中也有不仁的时候——仁是最高级的道德境界，哪怕是君子，也可能偶尔忘失本心、暂时不仁，或虽具备很高的政治、人文、道德修养，离仁仍有距离。孔子最得意的弟子颜回也不过是\"三月不违仁\"，其余弟子\"日月至焉而已\"，偶尔达到而已。而小人则绝不可能有仁德。\\n\\n理解本章不能停留于字面，否则不是流于\"必须身居高位才算仁\"的绝对，便是沦为道德修养的废话。孔子之意在于劝勉：不要做小人，要努力做君子；而成为君子仍不够，更须以仁为标准、志于仁。君子虽以仁为标准，却未必时时安住于仁——真能常安于仁者便是圣人，数百年一出；而君子只要肯努力，当世即可为之。想做君子并不难，文质彬彬、品行厚实、为众人认可即是；想不做小人也有简捷之法——志于仁。因为小人之为小人，正在于\"不耻不仁，不畏不义，不见利不劝\"，无利不起早，只认好处不认道义；一旦有志于仁，便跳出了小人的窠臼。\\n\\n孔子对仁者的标准特别高：或问子路、公西华、冉有能否称仁，皆曰不知；子贡自问何如，孔子只答\"器也\"，是人才而距仁者尚远。只有如大禹、后稷那样品德的最高体现，才可称得上真正的仁者。孔子为学做人总纲是\"志于道，据于德，依于仁，游于艺\"——以道为志向，以德为依据，依于仁这一德行的最高体现，再游习于百工技艺，方为完善的君子。\\n\\n本章对今人的启示尤为警策：仁的标准极高，君子尚会犯错、偶离仁境，何况今人多受小人之教，未曾习学何以为耻、何以为义、何以不见利忘义。人天性中既有本善的一面，也有先天自私自利、近乎小人的成分，须赖后天教化培养。正如魏征劝唐太宗所言：\"君子不能无小恶，恶不积，无妨于正道；小人或时有小善，不积不足以立忠。\"君子有小过而能即改，则无害于正道；小人偶有小善而不能积累，终不能立身。我们往往苛察君子之小过而轻信小人之小善，读此章当反躬自省：自己的发心与行为是否依于仁，是否志在成为谦谦君子。", keyPoint: "义利、仁德、教育" },
  { id: 454, chapterId: 14, order: 7, original: "子曰：“爱之，能勿劳乎？忠焉，能勿诲乎？”", translation: "孔子说：“爱他，能不以勤劳相劝勉吗？忠于他，能不以善言来教诲他吗？”", commentary: "①爱：爱他有多种指向——对下（领导爱下属、家长爱子女）、对自己、对上（爱父母亲人祖国）、对平辈朋友皆可。古代\"爱\"字有时近于贬义，指带私心的情感；真正的大爱谓之\"仁\"，\"仁者爱人\"，无私无忧。\\n②劳：一为勤劳、劳作；一为忧思、挂念（《诗经》中\"忧劳\"之义）。其古篆字形如门起火而救之状，兼指此心情与行动。\\n③忠：忠诚。焉作\"于之\"，即忠于别人；亦可作\"于此\"，指别人忠诚于我。\\n④诲：自己知道而别人不知道的，传授给他，谓之诲。与\"规\"（规劝改过）相通，臣子劝君主谓之\"规诲\"。\\n---\\n\\n【解读】本章可由多个角度理解，诸解看似不同甚至相矛盾，实则相通。上半句\"爱之，能勿劳乎\"：从对下说，爱下属、爱子女不是溺爱，不能剥夺其勤劳的义务与权利——如孟子所言\"天将降大任于斯人也，必先苦其心志，劳其筋骨\"，不使其劳，等于剥夺了天降的大任；从对自己说，真爱自己就不当安逸懈怠而走上错路；从对上说，爱父母、爱亲人、爱祖国，岂能不为其辛苦劳作。而\"劳\"字更有忧思之义，任何爱都隐含着关心挂念。由此反推，若能使爱纯净无杂，无忧无虑不需操劳，那便是解脱之境——只有经由勤劳、忧思的修证，才能达到无须修证的境界，绝非一上来便不劳不修。\\n\\n下半句\"忠焉，能勿诲乎\"同样多重：我忠于别人，自己会的岂能不告诉他；别人忠于我，我又岂能对他有所隐瞒；忠于祖国，则须忠心劝告统治者、尽其所知——古代布衣上万言书忧国忧民，近代公车上书，皆属此类。更深一层，忠于他也可解为忍住不把自己个人经验强加于他——他是白纸，我所会的未必通达无碍，若强教反可能使其犯经验主义、教条主义之错，倒不如让他自己去开拓创新。故上下两半实为互文：爱之忠之，既当尽心竭力、无私奉献，把所知所能都交付于他；亦当忍住不包办，让所爱所忠之人自能勤劳、自能创新。\\n\\n本章与前章\"君子而不仁者有矣夫\"及篇首\"宪问耻……邦有道谷\"义理一脉相承：爱国爱君，邦有道则出仕食禄、为其操劳劝诫。对今人的启示在于正确认识爱与忠、正确对待劳与诲；自己会的要教人，但须追本溯源——如朱熹诗\"问渠那得清如许？为有源头活水来\"，真正的道理在文字之外，须以如切如磋、如琢如磨的工夫不断磨练自心，志于道而求之，方能堪受此道。", keyPoint: "仁德、教育" },
  { id: 455, chapterId: 14, order: 8, original: "子曰：“为命，裨谌草创之，世叔讨论之，行人子羽修饰之，东里子产润色之。”", translation: "孔子说：“郑国制订外交文件，由裨谌起草，世叔提出意见，外交官子羽修改，东里子产作加工润色。”", commentary: "①为命：命指正式的外交国书，极其慎重；与日常外交应对的\"辞\"不同——辞可临时应对，命则写成定本，发表后可传之于百年甚至千年，今《尚书》所存诰命即此类。\\n②裨谌：郑国大夫，善于综合众人意见、多有谋略，负责草创，即起草初稿。\\n③世叔：又称太叔，郑国大夫。讨论在古代指检讨、议论，即发表意见、批评指正如何修改，与今义不同。\\n④行人子羽：行人是外交官之官名；子羽任外交官，因最终由他出使转达此命，故须参与修改润饰。\\n⑤东里子产：子产，郑国首相，长期主持内政外交，由他最后审定、润色，使文件增采得体。\\n---\\n\\n【解读】本章表面看孤立，实则把前几章\"爱之能勿劳乎，忠焉能勿诲乎\"的理落实在事上——为小国慎重制作外交文件，正是忠爱其国的具体实践。郑国本为春秋最早强大的国家，郑穆公号为春秋五霸第一霸，但因欺凌周王室而迅速衰落，至子产时已是小国，全靠君子的德行与感召才未被晋、楚吞并。君子对人民有恩惠，其恩惠主要通过内政与外交来体现：内政上子产创制刑书，把法律铸于鼎上，是为成文法之始；外交上则极其慎重，知人善任，以能言善辞、仪表出众的子羽等任外交官。\\n\\n命既如此慎重，制作流程便环环相扣：先由善于集思广益的裨谌草创起草，再由世叔讨论检讨、提出修改意见，再让最终出使转达此命的外交官子羽修饰润饰，最后子产亲自拍板润色，使它拿得出手。整个过程严谨严密，充分体现君子做事之慎重与善用人才。孔子曾赞子产\"有君子之道四焉：行己也恭，事上也敬，养民也惠，使民也义\"，本章正可见其一斑。\\n\\n可惜子产去世早于孔子，孔子过郑时未能相见，只留下\"丧家之犬\"的典故——弟子寻访孔子，郑人说东门外有一人状貌甚伟而神态惶惶如丧家之犬，此语即郑人所出。继子产执政的世叔亦未能承其遗风：子产曾告诫他，自己宽厚可行，而世叔嫉恶如仇，若照己方式执政必生乱子，后果然如此。可见君子之德行才干无法替代，出一个君子极不容易。\\n\\n对今人的启示有三：其一，做事须严谨，重要文件当如制作诰命般由团队分工、反复打磨，而非一人独断；其二，学习先贤君子做事之道，但须结合自身情况，不可照搬——郑国小国处境使其对君命极端重视，今日不必事事追求完美，宜在严谨与务实之间求平衡，不走向极端；其三，最根本的是提升个人修养，追求理想化人格，以孔子所称\"古之遗爱\"的子产为榜样。", keyPoint: "教育、知人" },
  { id: 456, chapterId: 14, order: 9, original: "或问子产，子曰：“惠人也。”问子西，曰：“彼哉，彼哉！”问管仲，曰：“人也。夺伯氏骈邑三百，饭疏食，没齿无怨言。”", translation: "有人问子产是怎样的人。孔子说：“是宽厚慈惠的人。”\\n问到子西是怎样的人。孔子说：“他呀!他呀!”\\n问到管仲是怎样的人。孔子说：“他是个人才。他剥夺了伯氏骈邑三百户的封地，使伯氏只能吃粗粮，却至死没有怨言。”", commentary: "①子产：郑国大夫，与孔子同时而稍早，长期执政。郑国处晋、楚两强之间，子产内政外交皆善，郑简公、郑定公时政通人和；他恪守礼制，外交上敢据正义指责晋国。孔子曾赞其有\"君子之道四焉\"。\\n②惠人也：惠，恩惠、施惠于人。人可解为大人物、领导，亦可通\"仁\"（仁德）。即谓子产是能授人恩惠、惠及民众的仁德之人。\\n③子西：春秋有三子西。一为子产宗亲、子产之前执政者，无甚事迹；二为楚国作乱被杀的子西；三为与孔子同时的楚国公子申，有逊位之德却未能阻止动乱，且曾阻止楚昭王任用孔子。\\n④管仲：齐桓公之相，辅桓公称霸、九合诸侯，亦吞并小国、有破坏礼制之举，历来评价复杂。孔子此处以\"人也\"（人通\"仁\"）赞之。\\n⑤伯氏：齐下大夫，其采邑骈邑三百家被齐桓公夺归管仲，伯氏自此饭粗食至死而无怨言，足见管仲德行之感召。\\n---\\n\\n【解读】本章紧承上章论子产制命之事，有人接连问起三位当世人物，孔子各以寥寥数语品评，用语极有分寸。子产内政外交皆有成就，使弱小的郑国在晋楚争霸的夹缝中保持安定繁荣，是名副其实的一代贤相，去世时万人空巷。孔子以\"惠人也\"三字给予极高评价——施惠于民、利他助人，便是君子最大的功绩，不必罗列政事；又因孔子曾言子产具君子之道四，故\"惠人\"亦可读作\"仁人\"，谓其具仁德。\\n\\n问及子西，孔子只道\"彼哉，彼哉\"，意思是\"他呀，他呀\"，不再多说，实为不予称赞。虽然问者或因公子申有逊位之德、政绩可观而期望好评，但在孔子看来不值一评；何况公子申未能阻止楚国生乱，又曾阻挠楚昭王任用孔子。孔子并无私怨，只是不评价其恶——君子成人之美，不成人之恶。\\n\\n问及管仲则颇为耐人寻味。孔子前此曾批评管仲\"器小\"、\"不知礼\"，此处却说\"人也\"（仁人），看似矛盾。其故有四：一是《论语》有鲁人传本与齐人传本之别，各有侧重；二是孔子之言本不矛盾——管仲确有体现仁德之处，而君子亦非时时皆仁，故当批评处仍批评，当赞扬处仍赞扬；三是君子对事不对人，批评是为使众人借此得启发，赞扬是为弘扬其惠利于民的品质，而非个人好恶；四是管仲之仁从其效果可见——伯氏被夺骈邑，饭粗食终老而毫无怨言，正说明管仲处事公平，使人心服。\\n\\n对今人的启示，在于学习孔子品评人物的态度与艺术：对有大功于民者不吝赞美，一句\"惠人也\"即是无尽褒扬；对不足为论者则不言其恶，一句\"彼哉\"轻轻带过；品评人物当取其闪光之处而学之，不盯其缺陷不放，纵要挑剔，也只挑自己的缺陷。", keyPoint: "仁德、君子小人、礼乐" },
  { id: 457, chapterId: 14, order: 10, original: "子曰：“贫而无怨难，富而无骄易。”", translation: "孔子说：“贫穷而没有怨恨很难，富贵而不骄矜至很容易。”", commentary: "①贫而无怨：贫贱而没有怨言。无怨即乐，此乐由乐道而来——安于仁、乐于道，则无论外界境遇如何皆坦然无怨。\\n②富而无骄：富贵而不骄傲。知\"不义而富且贵，于我如浮云\"，富贵本由义来、由仁生，是其应得之果，故无所可骄。\\n③安贫乐道：安于贫贱而乐于道义，是君子无论贫富皆当持守的境界。\\n④先难而后获：樊迟问仁，孔子答以\"先难而后获\"，即先做难事、不谋其获。贫而无怨正是这样的难事，做到方能近于仁。\\n---\\n\\n【解读】本章讲君子无论贫富皆当安贫乐道、不骄不躁。贫而无怨之所以难，在于怨即是乐之反面——能无怨，正是因为有乐，此乐自乐道而来；而富而无骄相对容易，因为富贵不过是努力应得的自然结果，知其因、明其过程，便无可骄——如学习用功、准备充分而考试及格，只是正常之事，不值得骄傲。\\n\\n本章与学而第一子贡所问\"贫而无谄，富而无骄，何如\"相通。孔子当时答以\"未若贫而乐道，富而好礼者也\"，谓不谄不骄仍嫌不足。由此推之，贫而无怨即是贫而乐道，是最高境界；富而无骄则居其次。贫而无怨之难，在于一个人纵已尽心尽力、言行合礼，仍可能贫贱——如颜回一箪食一瓢饮居陋巷，份内之事已做到最好，却因出身、境遇、不遇于君等个人无法改变之命数而不得显达。此时能否无怨，全看其对道、德、仁有无发自内心的追求：安于仁、乐于道者，外界贫困、道路不通、努力无果皆不能使之有怨，此方为真君子。\\n\\n现实观察亦可印证：不得志之人往往难以接受\"努力种因、莫重结果\"之理，而富贵之人衣食足而知礼节、富长良心，反而较易明白。但富而无骄亦非人人能之——现实中稍有余财便趾高气扬、以财富为成功标准者比比皆是，此乃等而下之，不足为法。我们当努力做到既富而无骄，又贫而无怨。贫而无怨虽难，却正应\"勉为其难\"——去做难的事，因为难事做不成，何谈仁道？正如孔子答樊迟问仁：先难而后获。这也是对前几章所论子产、管仲等富贵政治家的回应：他们皆能富而无骄，但那并非最高境界；贫而无怨，才是当追求的仁之境界。无论贫富皆无怨言、皆乐于道，人生便是充实美好的。", keyPoint: "义利、学习" },
  { id: 458, chapterId: 14, order: 11, original: "子曰：“孟公绰为赵、魏老则优，不可以为滕、薛大夫。”", translation: "孔子说：“孟公绰担任晋国的赵氏、魏氏的家臣是绰绰有余的，但是做不了滕国和薛国这样小国的大夫。”", commentary: "①孟公绰：鲁国大夫，孟孙氏族人，清心寡欲，无欲则刚，孔子敬之如父。\\n②老：家老，卿大夫家中的总管，相当于顾问之职，地位尊崇而事务清闲。\\n③优：有余力，能做得很好，行有余裕。\\n④赵、魏：晋国六卿中的赵氏、魏氏，当时晋国为中原遵周礼诸国中最强者。\\n⑤滕、薛：夹于鲁、卫、齐之间的两个东方小国。\\n---\\n\\n【解读】本章孔子评孟公绰之才性。孟公绰为鲁国孟孙氏族人，清心寡欲，无欲则刚，《史记》将孔子所严事之人列为：于周老子、于卫蘧伯玉、于齐晏平仲、于楚老莱子、于郑子产、于鲁孟公绰，孔子皆以对父之礼敬之，从其身上学习应学的品质。\\n\\n赵、魏为晋国上卿，其家老之职地位尊崇而事务清闲，实则顾问角色——说的话很有分量，可以影响赵魏，进而影响晋国乃至天下。孟公绰为赵魏之老，行有余力，做得很好。而滕、薛是夹于鲁、卫、齐之间的小国，内政外交头绪繁杂，大夫身当其任，地位高、责任重、事务繁忙，且一举一动须看大国脸色，身不由己。孟公绰性清心寡欲，做清闲的谋主之事游刃有余，做日理万机的小国执政则非其所长。\\n\\n孔子此评示人：用人不可求全责备。栋梁之材若拿去搭鸡窝，鸡窝搭不好，栋梁亦废；弯曲之藤不用以编筐而欲作栋梁，亦不能成。故当知人善任，各尽其才。孟公绰虽不能为滕薛大夫，然其不贪不求、明哲保身，看清乱世而无意做官，以人格魅力施惠于人，亦足称君子。\\n\\n由此引申，今人当正确认识自己之才干与所宜之场景，人生规划须建立于自知之上。人人皆可求为君子仁人——“我欲仁，斯仁至矣”，与阶级、出身、才干无关；但现实行事，仍须择己所擅长、合己之性者为之，方能把事情做好。", keyPoint: "宪问第十四" },
  { id: 459, chapterId: 14, order: 12, original: "子路问成人，子曰：“若臧武仲之知、公绰之不欲、卞庄子之勇、冉求之艺，文之以礼乐，亦可以为成人矣。”曰：“今之成人者何必然？见利思义，见危授命，久要不忘平生之言，亦可以为成人矣。”", translation: "子路问怎样才算是完人。孔子说：“像臧武仲那样有智慧，像孟公绰那样不贪求，像卞庄子那样勇敢，像冉求那样有才艺，再用礼乐来增加他的文采，就可以算个完人了。”孔子又说：“如今的完人何必要这样呢？见到利益能想到道义，遇到危险时肯献出生命，长期处在贫困之中也不忘平生的诺言，也就可以算是完人了。”", commentary: "①成人：完美的人、有成就的人，此处兼指成熟完整的领导者。\\n②臧武仲：鲁国大夫，以智慧著称。\\n③知：智慧。\\n④公绰：孟公绰，廉洁寡欲。\\n⑤不欲：没有贪欲、廉洁。\\n⑥卞庄子：鲁国卞地大夫，以勇著称。\\n⑦冉求：孔子弟子，多才多艺，为季氏家宰。\\n⑧文之以礼乐：以礼乐加以文饰、修养。\\n⑨见利思义：看见利益先想到道义。\\n⑩见危授命：遇到危难甘愿献出生命。\\n⑪久要不忘平生之言：长久处于困穷仍不忘记平日的诺言与志向。“要”通“约”，困顿、简朴。\\n---\\n\\n【解读】本章子路问成人，孔子提出两套标准，一层比一层平实。所谓“成人”，既可解作完美的人，亦可解作成熟、完整、有成就的人；“人”指士以上的阶层，犹言领导者，故子路所问实为怎样做一个好的领导、功成名就的士人。\\n\\n孔子先言最高标准：若兼具臧武仲之智、孟公绰之廉、卞庄子之勇、冉求之艺，再以礼乐文饰之，便可为成人。此四者皆为领导者——臧武仲为卿大夫，孟公绰为贵族，卞庄子为卞地之领袖，冉求为季氏家宰。其中臧武仲擅为人处世之智慧，卞庄子孝勇兼备、母亡后力尽而亡，冉求博学多能、深得季康子信任。礼是心对自己的约束，乐是内心和乐、与人融洽而不自我突出，故智、廉、勇、艺皆须以礼乐成就之。孔子又言“今之成人者何必然”，盖春秋末礼崩乐坏，礼乐之制已难凭恃，故降而为第二套标准：见利思义、见危授命、久要不忘平生之言，有此三者亦可为成人。见利思义最难——人常利令智昏，只做利己之事便沦为小人；见危授命是大勇；久要不忘平生之言是信，若连自己说过的话都记不得，所立志向岂能长远。\\n\\n本章对今人的启示在于：当观察自身性格，从智慧、廉洁、勇、艺何者入手，各品质可互相平衡补充——智慧而廉洁者往往不进取，须以勇气才艺济之。若求完美过难，则可从有恒入手，向着正确目标不断前进，亦能有所成就。", keyPoint: "为政、孝道、学习、诚信、齐家" },
  { id: 460, chapterId: 14, order: 13, original: "子问公叔文子于公明贾曰：“信乎，夫子不言，不笑，不取乎？”公明贾对曰：“以告者过也。夫子时然后言，人不厌其言；乐然后笑，人不厌其笑；义然后取，人不厌其取。”子曰：“其然？岂其然乎？”", translation: "孔子向公明贾问到公叔文子，说：“是真的吗？他老先生不言语、不笑、不取钱财？”公明贾回答说：“那是告诉你的人说错了。他老人家是到该说话时再说话，别人不讨厌他的话；高兴了才笑，别人不厌烦他的笑；应该取的时候才取，别人不厌恶他的取。”孔子说道：“是这样的吗？难道真的是这样的吗？”", commentary: "①公叔文子：卫国大夫，卫献公之孙，谥号“贞惠文”，正直、有恩惠而博学多能。\\n②公明贾：卫国人，卫国大夫，亲见公叔文子执政之言行。\\n③信乎：真的吗，可信吗。\\n④夫子：先生，古代对年长者的尊称。\\n⑤以告者过也：传话的人说得过头了。\\n⑥时然后言：到了恰当的时候才说话。\\n⑦乐然后笑：真正和乐时才笑。\\n⑧义然后取：合乎道义才收取。\\n⑨其然：是这样，肯定公明贾的解释。\\n⑩岂其然乎：难道真像传言所说的那样吗。\\n---\\n\\n【解读】本章紧承上章论“成人”而来。孔子向卫国公明贾求证关于公叔文子的传言。公叔文子是比孔子稍早的卫国名臣，卫献公之孙，曾辅佐年轻的卫灵公，去世后得“贞惠文”三字美谥——正直、惠人、博学；孔子至卫时他已去世，故向亲见其执政的公明贾请教。\\n\\n孔子听说公叔文子“不言、不笑、不取”，深表怀疑：既是血肉之躯，岂能不说话、不笑、不要钱？公明贾答“以告者过也”：先生到该说的时候才说话，故人不厌其言；真和乐时才笑，非谄笑、非讥笑，且是与众人同乐、后天下之乐而乐，故人不厌其笑；合乎道义才取，取之合于应得，故人不厌其取。\\n\\n对“其然，岂其然乎”的理解，对话中认为通行的问句翻译（“是这样吗？难道真是这样吗？”）解释不通——孔子见人善行必欢喜效法，不会无端怀疑。此处应译为肯定：公明贾说得对，是这个道理；难道真像传言说的那样吗？即“时然后言”被讹传为“不言”，“乐然后笑”讹为“不笑”，“义然后取”讹为“不取”——本是人人努力可学的君子境界，竟被传成天然与众不同、不食人间烟火的仙人，故孔子由疑而信，疑团得解。\\n\\n本章启示有二：一是转述、评价人事物不可夸大其词，要看到本质；二是有疑问要找明白人求教，不能信谣言流言。孔子之所以学问广博，既因好学读书，亦因“入太庙每事问”，事事向接近事实的人请教。", keyPoint: "学习、教育" },
  { id: 461, chapterId: 14, order: 14, original: "子曰：“臧武仲以防求为后于鲁，虽曰不要君，吾不信也。”", translation: "孔子说：“臧武仲凭借防邑请求立他的后代为鲁国的卿大夫，虽然有人说他不是要挟国君，我是不信的。”", commentary: "①臧武仲：鲁国大夫，世代为鲁国司寇，以智慧著称。\\n②防：臧武仲的封地防城。\\n③求为后：请求国君立其子嗣为继承人，继续在封地享受官爵禄位。\\n④要：要挟，凭恃所拥之物而强求于君上。\\n⑤不信：不相信，指孔子不信其未要挟君上。\\n---\\n\\n【解读】本章评臧武仲出奔前以封地防城要君之事。史载鲁襄公二十三年，臧武仲得罪季孙氏，季武子欲杀之，他先奔邾国，后回防城，向鲁君请求立其子臧为为继承人，方离国出亡齐国。孔子认为此举不合礼。\\n\\n此事虽有可体谅之处——大臣因得罪权臣而失势，临行求君主保全后嗣，乃人之常情——但其中隐含有“不立吾子，吾将如何”的要挟意味。纵使本无此心，旁人亦难免作此想，故为不当。“吾不信也”有二解：一解为孔子批评他要挟君上——封地本为君赐，废立之事非臣下可自专，出奔逃亡仍要求君立嗣，逾分越礼；另一解谓其本无要挟之心，然孔子仍不予采信。无论何解，孔子批评之意显见。\\n\\n值得深思的是，前章孔子才赞“若臧武仲之知”，称其智慧；如此聪明之人，仍不免做出以封地要君、破坏礼制的事，最终自食其果，离开封地流亡他国。可见智慧若不以礼乐、道义为基础，便易流为小聪明。臧武仲曾预言孔子之先祖将出圣人，对孔子有知遇之恩，故孔子此评非求全责备，而是叹其于礼乐尚有不通达之处——联系子路问成人章，礼乐正是成人之要，缺礼乐之文饰，则智、廉、勇、艺皆不足恃。\\n\\n本章对今人的启示在于：不可片面追求智慧，更当追求规则、仁义、道德这些最稳固的基础；知识与智慧有时会变成小聪明，反而害了自己。", keyPoint: "仁德" },
  { id: 462, chapterId: 14, order: 15, original: "子曰：“晋文公谲而不正，齐桓公正而不谲。”", translation: "孔子说：“晋文公诡诈而不正派，齐桓公正派而不诡诈。”", commentary: "①晋文公：名重耳，春秋五霸之一，晋国国君。\\n②齐桓公：名小白，春秋五霸之一，齐国国君。\\n③谲：诡诈、欺诈，玩弄权术。\\n④正：正派，合于正道。\\n⑤不谲：不用诡诈的手段。\\n---\\n\\n【解读】本章孔子评价晋、齐两位霸主的用心术数。齐桓公称霸早于晋文公，晋文公流亡途中还曾受齐桓公安置房舍之惠，二人有过交集。\\n\\n晋文公一生传奇：年少历经骊姬之乱，流亡郑、卫、曹等国；归国复位后，讨伐流亡途中慢待他的姬姓之国，更以臣子身份召周王会盟、以诸侯之礼对待周王并使其一同狩猎，故孔子著《春秋》为周王讳，书“天王狩于河阳”，并谓“以臣召君，不可以训”。其用兵亦多诡道：城濮之战前承诺退避三舍，却不直接与楚交战，先伐卫而引楚军来战。盖其早年漂泊，深知权力由暴力与实力产生，而非凭仁义正道，故以心术登上霸位。一直追随他的介子推在他即位后便隐居绵山，他放火烧山欲逼介子推下山，介子推竟被烧死山中，遂有寒食节流传——君子在其上位之时即相率离去，足见其心术之不正。\\n\\n齐桓公则正而不谲：他私德有亏，好色、刚愎自用，不听扁鹊之谏（史书避讳作蔡桓公），病入膏肓而早逝；然行事循于正道——伐楚以周昭王溺于楚地、楚三年不进贡包茅为名，名正言顺；任用曾射其衣钩的管仲为相，有政治家的恢弘气度；九合诸侯不以兵车，打着尊王攘夷的旗号而不用武力胁迫，不逼迫周天子，会盟后小国倚之，帮助中原诸国，大体尊重周礼。\\n\\n孔子此评意在引导人们学齐桓公而不学晋文公。诡谲不正虽亦能成霸业，但不可鼓励效法，学之容易学坏。晋文公才具过人、注重名声，然以心术处世，终失君子之道。本章对今人的启示在于：人皆复杂，欲成就真正的君子，不仅要有智慧、不欲、勇气、才艺与德行，更要坚持走正道；不学霸主们为利益勾心斗角，而当效法仁者圣者之作为。", keyPoint: "仁德、礼乐" },
  { id: 463, chapterId: 14, order: 16, original: "子路曰：“桓公杀公子纠，召忽死之，管仲不死，曰未仁乎？”子曰：“桓公九合诸侯不以兵车，管仲之力也。如其仁，如其仁！”", translation: "子路说：“齐桓公杀了公子纠，召忽自杀以殉，但管仲却没有死。”接着又说：“管仲是不仁吧？”孔子说：“桓公多次召集各诸侯国盟会，不用武力，都是管仲出的力。这就是他的仁德！这就是他的仁德！”", commentary: "①桓公：齐桓公，齐僖公之子，名小白，春秋五霸之一。\\n②公子纠：齐桓公的异母兄，其傅为召忽、管仲。\\n③召忽：公子纠之傅，公子纠被杀后自杀殉主。\\n④管仲：公子纠之傅，后为齐桓公相，辅佐其成就霸业。\\n⑤九合诸侯：多次会合诸侯。“九”或为虚数；一说通“纠”，纠合、聚合。\\n⑥以兵车：以武力胁迫。\\n⑦如：比得上、像……一样。如其仁，谁有他这样的仁德。\\n---\\n\\n【解读】本章借子路之问，孔子再次评价齐桓公与管仲。子路以管仲未随公子纠殉死而疑其不仁，孔子则盛赞“桓公九合诸侯，不以兵车，管仲之力也。如其仁，如其仁”。\\n\\n史事本末：齐襄公荒淫无道，公子纠与公子小白各自在师傅保护下出奔——公子纠随召忽、管仲居鲁，公子小白由鲍叔牙安排居莒，因莒离齐较近，便于及时归国。齐襄公被杀、公孙无知自立又被杀后，兄弟二人争位。管仲半路伏击小白，一箭射中其衣钩，小白装死，管仲遂报喜于鲁，鲁国慢慢护送公子纠回国，六日方至，而小白已在鲍叔牙帮助下继位。齐桓公即位后逼鲁杀公子纠，召忽以主君已死、义不独存而自杀；管仲则忍辱负重，被囚车拉回齐国，桓公大度地说“各为其主”，听鲍叔牙之荐拜其为相、尊为仲父。管仲遂施展经世之才，使齐国富强，著《管子》传世，影响深远。\\n\\n“九合诸侯”一说实有九次会盟，尊周天子、恢复周礼、共御外族；一说“九”通“纠”，为纠合、监督聚合之义；清人又考证桓公会盟不止九次，故以九为虚数。无论何解，桓公多次会盟而不以武力胁迫诸侯，皆管仲之力。\\n\\n孔子论人，不斤斤于私德小节：桓公、管仲虽私德有亏，然在大节上功业昭著，故许管仲为仁。召忽殉主，义气可嘉，然不过顾全小节，于历史无大贡献；管仲忍辱事功，泽被天下，故诸葛亮自比管仲、乐毅，其名传千古，而召忽则少有人知。本章对今人的启示在于：评价历史人物不可片面，当考量其初心与对历史的贡献；自己行事须按仁德要求，而知仁离不开学，故当学无止境。", keyPoint: "为政、学习、教育、齐家" },
  { id: 464, chapterId: 14, order: 17, original: "子贡曰：“管仲非仁者与？桓公杀公子纠，不能死，又相之。”子曰：“管仲相桓公霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。岂若匹夫匹妇之为谅也，自经于沟渎而莫之知也。”", translation: "子贡说：“管仲不是仁人吧？齐桓公杀了公子纠，他不能以死相殉，反又去辅佐齐桓公。”孔子说：“管仲辅佐齐桓公，称霸诸侯，匡正天下一切，人民到现在还受到他的好处。如果没有管仲，我们大概都会披散着头发，衣襟向左边开了。难道他要像普通男女那样守着小节小信，在山沟中上吊自杀而没有人知道吗？”", commentary: "①相之：辅助他（指齐桓公）。相，辅佐。管仲未随公子纠殉死，反而辅佐其政敌齐桓公，此为子贡质疑的焦点。\\n②一匡天下：匡正天下。管仲辅佐齐桓公称霸诸侯，使天下秩序得以匡正。\\n③微：假使没有。\"微管仲\"即\"如果没有管仲\"。\\n④被发左衽：披散头发、衣襟向左，指当时戎狄等外族的服饰礼节，与中原衣冠文明相对。孔子借此比喻中原文明若被外族吞并后的生存状态。\\n⑤匹夫匹妇之为谅：普通男女所拘守的小信。谅，小信、固执于小节。谓不能要求管仲像普通人那样拘于小忠小信。\\n⑥自经于沟渎：在山沟小河中自缢而死。自经，上吊自杀；沟渎，一说泛指沟渠小河，一说为地名。\\n---\\n\\n【解读】本章与前章（子路问管仲）同答一题：管仲是否为仁者。前一章子路以召忽殉死、管仲独存作对比，质疑管仲不仁；此章子贡更进一步，谓管仲不但不死于公子纠之难，反而辅佐杀主之齐桓公，岂非不仁不义。此处子贡实将\"忠\"与\"仁\"相混淆——忠有小忠与大忠之分，须辨其忠于所辅之君，抑或忠于道义本身。孔子答以\"一匡天下，民到于今受其赐\"：管仲匡扶正道、抵御外族，使百姓蒙受恩泽，此乃最大的仁道。这与前文批评管仲\"器小\"、私德有亏并不矛盾——一个人纵使私德完备，若不能惠及天下，便难称最高之仁德。管仲具备仁德，并不意味着其个性心性圆满无缺。\\n\\n管仲惠及百姓之处，史书记载甚多：既使齐国富庶，又助诸侯会盟、尊奉周天子。其时东周自平王东迁已逾百年，王室衰微，周王在诸侯心中徒具象征地位，管仲却能对周室示以礼敬，致力于复兴周礼。据《史记》所载，齐桓公在位期间，管仲伐山戎以救燕、南伐召陵、西涉流沙、登太行以御戎狄，中原与戎狄之界赖此而守。孔子所言\"被发左衽\"亦非夸张：披发不冠、衣襟向左，皆为外族之礼。若中原文明为戎狄所灭，华夏衣冠礼仪将荡然无存，故管仲保全中原礼乐文明，其功至伟，岂能责其拘于匹夫之小信小节？召忽虽为贤者，殉主而死，却未必合乎仁道。\\n\\n本章之要义在于评价人物须全面而立体。人甚复杂，当观其对历史的贡献，不可用普通人的标准求全责备。子贡、子路皆为杰出弟子，于此尚难企及夫子之境界，足见圣人之心传不易得。今人学习榜样，宜取最高标准，学颜回、学孔子，方不至有所偏颇。", keyPoint: "仁德、学习、教育" },
  { id: 465, chapterId: 14, order: 18, original: "公叔文子之臣大夫僎与文子同升诸公，子闻之,曰：“可以为‘文’矣。”", translation: "公叔文子的家臣大夫僎，（被文子推荐）和文子一起擢升为卫国的大臣。孔子听说了这件事，说：“可以给他“文”的谥号了。”", commentary: "①公叔文子：即公叔拔，卫献公之孙，卫国贤臣，谥号\"文\"（实际谥号为\"贞惠文\"三字）。\\n②臣大夫僎：僎，人名，公叔文子的家臣，出身平凡，无姓氏可考。古人或把\"臣大夫\"连读，指大夫的下属；也可分开读为\"公叔文子之臣，大夫僎\"，因僎后经举荐亦为卫国大夫。\\n③同升诸公：一同升入公朝为大臣。诸，之于。指公叔文子举荐家臣僎，使之与自己同为卫国大夫。\\n④可以为文矣：可以称得上\"文\"这个谥号。据《周书·谥法解》，\"文\"有经纬天地、道德博厚、学勤好问、慈惠爱民、悯民惠礼、赐民爵位等六种含义，是极美好的谥号。\\n---\\n\\n【解读】本章继前文之后再次评价卫国贤臣公叔文子。前文已言其\"时然后言，乐然后笑，义然后取\"，是一位正派君子；此章则述其推举家臣僎，使僎与自己同列朝班。僎本是一介平民，没有姓氏，先为公叔文子之家臣，后因举荐而升为大夫。孔子闻之，赞其当得起\"文\"之美谥。公叔文子实际谥号为\"贞惠文\"三字，此处单称\"文\"，因\"文\"实为极美好的谥号，可兼涵\"贞\"\"惠\"之美。据《周书·谥法解》，\"文\"有经纬天地、道德博厚、学勤好问、慈惠爱民、悯民惠礼、赐民爵位六义，公叔文子之慈惠爱民、赐民爵位皆可当之。\\n\\n举荐才德之人，看似容易，实则需要极大的胸怀。设身处地而言，后辈或下属能力卓著，能否放下私心举荐他做到与自己同等的位子，甚至超过自己？很多人即便举荐，日后交往也难免仍以晚辈视之，不能平等待之，做不到\"选贤与能，讲信修睦\"。《礼记》言\"大道之行也，天下为公\"，此语为孙中山先生一生之理想，亦为我辈所继承，公叔文子所为正合\"选贤与能\"之义。由此亦可联系前几章所讲管仲：管仲正是由鲍叔牙举荐为相，鲍叔牙自甘居其下，其风范与公叔文子如出一辙。此外，卫国另有一位孔文子（孔圉）亦得\"文\"谥，子贡曾不服其私德，孔子答以\"敏而好学，不耻下问\"，可见评价一人当多看其长处。\\n\\n君子之美德实为相通。诸位君子言行表面或有差异，其本质皆依于道、德、仁、义、礼，正如佛家所谓\"一切圣贤，皆以无为法而有差别\"。学《论语》当透过现象看本质，学其本真一贯之真理。本章亦可见卫灵公虽个性古怪、贪财好色，大节上对待贤臣却颇厚道，谥号亦符合标准，可谓从善如流。对今人而言，公叔文子举贤之胸怀正是修身处世的最好镜鉴。", keyPoint: "学习、教育" },
  { id: 466, chapterId: 14, order: 19, original: "子言卫灵公之无道也，康子曰：“夫如是，奚而不丧？”孔子曰：“仲叔圉治宾客，祝鮀治宗庙，王孙贾治军旅，夫如是，奚其丧？”", translation: "孔子谈到卫灵公的昏庸无道，季康子说：“既然这样，为什么没有丧国呢？“孔子说：“他有仲叔圉接侍宾客，祝鮀管治宗庙祭祀，王孙贾统率军队。像这样，怎么会丧国？”", commentary: "①夫如是：既然像这样。夫，语气词，表发端。\\n②奚而：为什么。\"奚而不丧\"即为何不亡国；下文\"奚其丧\"意同。\\n③仲叔圉：即孔圉、孔文子，卫国大夫，善于应对宾客，负责外交事务。\\n④祝鮀：即子鱼，卫国大夫，能言善辩、深谙宗庙典礼仪节，负责管理宗庙祭祀。\\n⑤王孙贾：卫国大夫，善于政治军事，负责统领军队。\\n---\\n\\n【解读】本章记孔子与季康子论卫灵公。孔子言卫灵公治国无道，季康子遂生疑问：既然无道，卫国为何未亡？孔子答以卫国三贤各当其任：仲叔圉（即孔文子）治宾客，掌外交；祝鮀治宗庙，主内政之祭祀；王孙贾治军旅，统国防。一个国家不外乎外交、内政、军务三端，卫灵公皆任用了有水平的人，且各用其长，故不至于丧国。由此可知，为政者自身水平即便不高，只要善于用人、用人不疑、用其所长，国事仍可有所进展。\\n\\n卫灵公其人颇为复杂。孔子曾叹其\"吾未见好德如好色者\"，给予孔子俸禄却未重用之；本篇下一篇即以卫灵公发问引出孔子论政，然其问兵阵之事，孔子遂不答而去。其谥号\"灵\"亦非美谥，谥法谓\"乱而不损\"或\"好祭鬼神\"为灵，可见其举措混乱，幸而无大损。但他尊重贤才，大节未亏：祝鮀以善辩著称，王孙贾长于政治、深谙世情，孔子亦曾谓\"不有祝鮀之佞，而有宋朝之美，难乎免于今之世矣\"。卫国人才济济，灵公能各用其长，终未衰亡。相比之下，齐国仅得管仲一人便迅速富强，可见大才之难得。管仲或私德有亏、器量狭小，却无碍其为仁者、为能施惠于民的贤才。故评价人物，标准不可定得狭隘。\\n\\n本章对今人启示有二：其一，当善于发现他人长处，交往任用之时用其优势、凸显其价值；自身不及卫灵公者当学其用人，已达其境者更当自勉，勿蹈荒淫无道之覆辙。其二，若卫灵公、齐桓公能以君子的修养配合天生的资质，成就必不止于此，故归根结底仍须回归修身，以修身为本——把希望寄托于他人，终究是靠不住的。", keyPoint: "为政、仁德、修身、学习、礼乐" },
  { id: 467, chapterId: 14, order: 20, original: "子曰：“其言之不怍，则为之也难。”", translation: "孔子说：“说话大言不惭，实行这些话就很难。”", commentary: "①怍（zuò）：惭愧。因内心愧疚而脸上微微变色，谓之怍。\\n②言之不怍：说话大言不惭、面不改色。言者或觉胸有成竹、轻而易举，或根本未思如何践行，只是从道理上泛泛而谈。\\n③为之也难：做起来就难了。言其光说不做、说到难做到。\\n---\\n\\n【解读】本章所讲道理简单却常被忽视：凡事说起来容易，做起来难；越是说得轻松、大言不惭的人，往往越做不到。\"怍\"是因愧疚而脸红变色之意。说话时面不改色，或因胸有成竹，视其轻易，觉得轻轻松松便能办到；或因根本未思及如何实施，只是从道理上泛泛而谈，不过是\"看人挑担不吃力\"。孔子于此处借一句简言，为前面数章作一收束总结。\\n\\n前几章中，子路、子贡评论管仲，说其应当殉主而死，说得头头是道、毫无惭愧，然而若将自己置于管仲之位，方知其难；公叔文子举荐家臣与自己同朝为臣，说起来也不过一句\"君子当有此胸怀\"，然身处其位、放下私心举贤，方知其难；季康子讥卫灵公无道而不亡，亦未看到灵公之难处与长处。孔子故曰：道理讲来容易，做起来难。真正的君子能见事之难，故不轻易许诺，言语谨慎。卫灵公虽荒淫，然待君子以礼：史鱼进见时，他整肃衣冠、屏退左右，执笏捧札毕恭毕敬；对孔子亦礼遇有加、俸禄不减。他说话亦有惭愧之心，从不夸口，自知小国能立于列国已属不易。\\n\\n此章正合\"君子欲敏于行而讷于言\"之旨。孔子晚年归鲁，仍时时怀念卫灵公，正因其待人以诚、不作空言。对今人而言，切勿说大话、夸海口。说大话而无惭愧之心，恰说明只是说说而已，并无践行之意；若有心去做，开口时内心必生忐忑，脸上或会变色，会先掂量自己有多少能力再言。想要践行己言，实则极难，故当三思而后言，不要随意开口许诺。", keyPoint: "教育、知人、言行" },
  { id: 468, chapterId: 14, order: 21, original: "陈成子弑简公，孔子沐浴而朝，告于哀公曰：“陈恒弑其君，请讨之。”公曰：“告夫三子。”,孔子曰：“以吾从大夫之后，不敢不告也，君曰‘告夫三子’者！”之三子告，不可。孔子曰：“以吾从大夫之后，不敢不告也。”", translation: "陈成子杀了齐简公。孔子在家斋戒沐浴后去朝见鲁哀公，告诉哀公说：“陈恒杀了他的君主，请出兵讨伐他。”哀公说：“你去向季孙、仲孙、孟孙三人报告吧！”孔子退朝后说：“因为我曾经做过大夫，不敢不来报告。可君主却对我说‘去向那三人报告’。”孔子到季孙、叔孙、孟孙三人那里去报告，他们不同意讨伐。孔子说：“因为我曾经做过大夫，不敢不报告。”", commentary: "①弑：臣杀君、子杀父之谓，为大逆不道之行。\\n②陈成子：即田成子，名陈恒（亦作田常），其先祖由陈国奔齐，至其已历六世而改姓田。他与父亲陈僖子逐步架空齐君，为日后\"田氏代齐\"之始。\\n③沐浴而朝：沐浴斋戒后上朝，以示对讨逆大事的郑重恭敬。\\n④告夫三子：告知那三位大臣，即季孙、仲孙、孟孙三家（三桓）。鲁国军权实际掌握在他们手中。\\n⑤从大夫之后：谦辞，谓自己曾忝列大夫之列，即做过大夫。依礼，此等大事必须向国君禀报。\\n---\\n\\n【解读】本章记陈成子弑齐简公后孔子的反应。陈成子即田常，其先祖由陈国奔齐，至其已历六世而改姓田，与父亲陈僖子以\"大斗出、小斗进\"等小惠逐步收买民心、架空齐君，为日后\"田氏代齐\"之始。孔子时已七十余岁，闻此大逆，沐浴斋戒郑重上朝，请鲁哀公出兵讨伐，以为据周礼，臣弑其君，天下之人皆得而诛之。哀公以军权在三桓之手为由，令孔子去告知三子。孔子退出后申明：自己既曾为大夫，此等大事不敢不禀报，尽到了应尽之责；然君主既命告知三子，便往三子处报告，三子却以私欲为由不肯出兵。\\n\\n孔子此举，一面尽其为臣之义，一面借机昭示正义、正告乱臣贼子，为其盖上历史定论。三桓架空鲁君，其本质与陈成子相类，自不肯为正义牺牲自家利益。孔子陈请讨贼，并非\"言之不怍\"：他斋戒沐浴、郑重其事，且当时齐国内部一半人并不支持陈成子，若鲁国尽起大军、联合周边诸侯——其时子路尚在卫国掌权——拨乱反正并非无望。孔子此举本于春秋大义，欲兴灭国、继绝世，而非趁乱侵齐。无奈鲁国自身已失道，三子又囿于私欲，未悟唇亡齿寒之理，讨逆之议终成泡影。\\n\\n本章最深的启示在于：在历史大势与世道衰颓面前，君子所能做的便是尽自己的职责与义务，是非成败留待历史评判。陈成子辈或风光一时，却留下千秋骂名；孔子一生虽多无奈，却做到言行如一、所言所行皆出于本心，其精神影响中华文化两千余年，为后世立下最切实的表率。今人学做君子，正当学孔子这般，笃信己道、执着坚守，虽未必当世见功，然千秋功罪自有公论。", keyPoint: "为政、教育" },
  { id: 469, chapterId: 14, order: 22, original: "子路问事君，子曰：“勿欺也，而犯之。”", translation: "子路问怎样服侍君主。孔子说:“不要欺骗他，但可以犯颜直谏。”", commentary: "①事君：侍奉君主、为君效命。\\n②勿欺：不要欺骗。欺含自欺与欺人两层：既要看清事实、不自欺，也不隐瞒君主，无所隐瞒谓之无隐。\\n③犯之：犯颜直谏。犯，冒犯、触犯，即说君主不喜欢听但合理的话，如忠言逆耳。\\n---\\n\\n【解读】本章记子路问事君之道，孔子答以\"勿欺也，而犯之\"。此问承接前章孔子讨陈成子之事而来，孔子遂以事君之道为诸章作一总结。犯颜直谏，子路素能做到；难者在\"勿欺\"。勿欺者，一是不自欺——对事情看得清楚全面，所持的道理并非为达成一己之目的；二是对君主无所隐瞒，有何想法便如实汇报沟通，如孔子闻陈成子弑君即斋戒沐浴、上朝进谏，毫无隐讳。若怀欺君之心，凡事想瞒过君主，便必然不敢犯颜直谏，因为直谏有风险，会影响君主对自己的观感。\\n\\n人之常情都不喜听逆耳之言，屡屡进谏还恐招致羞辱，如\"事君数，斯辱矣\"所示。然若能大公无私、不为己谋，则自然无隐，看到什么便表达什么，好话坏话都肯讲。此正如《孝经》所言\"故当不义，臣不可不争于君\"，《礼记》所言\"事君有犯而无隐\"，亦与本章前文\"忠焉，能勿诲乎\"一脉相承。孔子教子路的，正是这看似简单的大道：只要无所隐瞒，直言相谏便好，但前提在\"勿欺\"，而勿欺之本又在于不自欺。不自欺的要求极高，达摩东渡，谓寻一\"不自欺\"之人而十余年难得；内观自心，人常自欺而不觉——以恶小而为之、以善小而不为，皆是自欺。\\n\\n最大的自欺，莫过于自认\"圣贤非我辈能为\"，失去上进之心，自甘堕落。故勿欺与犯之不可颠倒次序：并非为冒犯而冒犯、为显己能，而是本于勿欺之诚心，此心即忠信仁义、即礼节道德。人能不自欺、不欺人，则不独事君，待人接物皆能尽善，可称正人君子、道德模范。", keyPoint: "义利、孝道、教育" },
  { id: 470, chapterId: 14, order: 23, original: "子曰：“君子上达，小人下达。”", translation: "孔子说：“君子向上去通达仁义，小人向下去通达财利。”", commentary: "①上达：向上通达。依《易经》\"形而上者谓之道，形而下者谓之器\"，上即道、真理、仁义，下即器、功用、财利。君子向上通达于道。\\n②下达：向下通达。小人向下追求器用、财利与眼前利益。\\n③达：到达，亦含通达、通行、共通之意，谓与道相通无碍。\\n---\\n\\n【解读】本章将君子与小人并举，与\"君子喻于义，小人喻于利\"义相近。此处君子小人之别，是从道德修养立论，而非阶级地位：追求什么并不受阶级限制，平凡百姓亦可以通达仁义为志，然成就功业之大者则受时势所限，故本章是从理上立言。上与下之别，正如《易经》所谓\"形而上者谓之道，形而下者谓之器\"：君子追求道、追求真理，小人追求器、追求应用与财利。\"达\"兼有到达与通达之义，君子与道相通，故能\"君子不器\"，不受形质所限、不自设藩篱，于道中平等看待万物，如佛家\"是法平等\"，如庄子\"道在屎溺\"。\\n\\n小人下达，则是对形而下之器、具体之功用兴趣浓厚，学而修之不过为谋生糊口。君子为发展，小人为生存，二者非截然对立，而是对立统一：上达是升华，下达是现实。若将\"达\"作通达解，则君子与小人均须互相学习、共同成就，方能圆融圆满。然本章仍可作褒君子、贬小人之读：上达如登山，道为最高峰，登顶则高屋建瓴、无须牵挂形下之事；下达如水，流得好可汇入大海，流得不好便消失于地面，且易自我设限，湮没高明之仁义。小人追逐财利，为人欲所蒙蔽拘锁，故小人不能成君子，君子却能理解小人。在君子看来，小人以为空幻的仁义恰恰实实在在，小人看重的财利反而是\"不义而富且贵，于我如浮云\"。\\n\\n对今人而言，为学读书当有积极向上之精神，求思想内涵之成就于自身，与下章\"古之学者为己\"相呼应。下达之路无穷无尽，上达之路则有止境，止于至善、止于本心。故勿一味顺从后天私欲，当能\"逆天改命\"，克服天生的自私自利，而这一切皆离不开学——无论上达下达，欲为优秀之人，皆须终身学习。", keyPoint: "义利、修身、君子小人" },
  { id: 471, chapterId: 14, order: 24, original: "子曰：“古之学者为己，今之学者为人。”", translation: "孔子说：“古代学者学习是为了充实提高自己，现在的学者学习是为了装饰给别人看。”", commentary: "①古之学者：古代的求学之人。\"古\"非纯时间概念，而指文明初创时发心纯正、本真质朴的理想状态。\\n②为（wéi）己：成就自己。为，作为、修为；或加单人旁成\"伪\"，谓人为造作、不自然。\\n③为（wèi）人：为了别人，为取悦、装饰自己而给别人看。\\n④今之学者：当今的求学之人，多带世俗功利目的，学为外在的文凭、任务与评价，而非发自本心。\\n---\\n\\n【解读】本章孔子提出精辟论断：古今学者为学之目的不同。古之学者为己，其发心纯正，学在丰富、修正自己；今之学者为人，学以装饰自己、取悦他人。孔子所谓\"古\"，乃文明初创、发心本真的状态，非简单的时间先后——正如其\"好古，敏而求之\"，所好者是文明之本根。中国文化成熟极早，黄帝时已立衣冠礼仪之巅峰，此后数千年不过降本流末、开枝散叶，根干早已树立，春秋战国已臻文明之顶峰，故后世为学实是归溯文化之根。\\n\\n古之学者为己，主观客观皆为自己，然而真正学得好的君子反成万世表率，是为\"君子上达\"。今之学者多带强烈的功利性，学为考试、文凭、任务而发，目的非由内而生，动力不足，遂生厌学之心，今日亦然——多少人学习是为他人安排的目的，而非发自内心、乐此不疲。整部《论语》可用一字概括为\"学\"，学乃成就之途径，然今日\"为别人而学\"却使学习沦为中性乃至带附加条件的词汇。当然，为尽孝、为子女、为众人而学，发心亦甚伟大，只是往往违背天性、属被强扭之举。\\n\\n\"为\"字两读两解皆可通。为（wéi）己，谓修身唯一在成就自己、从自身下手；为（wéi）人，谓学有所成者须指引、修正他人，亦是不得不为之。故不必厚古薄今：古为理想状态，今为现实之不得不接受者。理想之学如马克思所论人的全面发展与自由解放，然其途径亦从为己始——不识自身之天赋与缺陷，何谈自由解放，此即修身齐家治国平天下之道。而人为社会关系之总和，亦可借成就他人而成就自己，如稻盛和夫所倡利他。己欲立而立人，己欲达而达人，真正的为己与为人本自相通，唯须先寻根向内，本心不在外求也。", keyPoint: "为政、修身、孝道、学习、教育、齐家" },
  { id: 472, chapterId: 14, order: 25, original: "蘧伯玉使人于孔子，孔子与之坐而问焉，曰：“夫子何为？”对曰：“夫子欲寡其过而未能也。”使者出，子曰：“使乎！使乎！”", translation: "蘧伯玉派使者去拜访孔子，孔子请使者坐下，然后问道：“先生近来在做什么呢？”使者回答说：“先生想要减少自己的过失但还没能做到。”使者出去之后，孔子说：“好一位使者呀！好一位使者呀！”", commentary: "①使：派遣、出使。此处\"使人\"即派人前往问候。\\n②与之坐：给他一个席位就坐。与，给予；坐，座位、席位。\\n③夫子：对他人的敬称，此处指卫国上大夫蘧伯玉。\\n④寡其过：减少自己的过错。寡，减少、减轻。\\n⑤未能也：还未能做到。也，句末语气词。\"未能\"二字不可轻轻看过，它隐含着求索之路的无止境，也点出政事尚有不能尽如人意之处。\\n⑥使乎：好一位使者啊。使，使者；乎，感叹语气词。连言\"使乎！使乎！\"，极言赞叹。\\n---\\n\\n【解读】本章记述卫国上大夫蘧伯玉派人探望孔子的一段对话。使者答以\"夫子欲寡其过而未能也\"，孔子在使者退出后连赞\"使乎！使乎！\"。表面上是一件简单的历史小事，实则蕴含深厚。\\n\\n蘧伯玉是卫国著名的君子，姬姓蘧氏，为周王室后裔。他比孔子年长三十岁，孔子视之如父，《史记》记载孔子以对待父亲之礼待之者，在周为老子，在郑为子产，在卫即蘧伯玉，二人之间是亦师亦友的关系。蘧伯玉学风纯正，有古之学者为己的遗风，专注在减少自己的过错上。他长期在卫国执政，风格是无为而治，凡事从自身做起，己欲正而正人，不施严刑峻法，不用投机取巧的手段，光明正大、身先士卒。历史上有他夜过公门仍下车行礼的典故；《淮南子》亦载\"蘧伯玉年五十，知四十九年之非\"，到了五十岁还在不断发现自己先前行为的过失而加以改正。他又以\"耻独为君子\"为念，因朝政混乱、礼崩乐坏，虽君子在位亦只能使卫国人口繁庶，难以完全达成天下太平之愿。\\n\\n使者寥寥数语，意涵颇深。\"欲寡其过\"是修身，而在君子看来修身即是为政，正己即是正人；\"未能也\"既表明求索无止境、不断在进步，又坦诚卫国政事尚有许多不尽如人意处，甚至连自己都还未有能力完全转变。这恰是实事求是、求真的精神。孔子不当面夸赞使者，待其出去后才对弟子们赞叹，因为当面不便称赞来客。使者的答对不辱君命、言简意赅，既道出圣贤为学与为政之道皆在寡过，又替卫国君主作了现实的说明。\\n\\n对今人的启示有三：其一，学习蘧伯玉欲寡其过而未能的精神，即使未能立刻做到也不灰心丧气，射不主皮，为力不同科，只要朝目标方向努力即可；其二，学习使者，为人办事要认清所服务之人的品格与要求，做到不辱使命；其三，学习孔子不吝于对他人优点的赞扬，并善于把细小的好处记录下来。能真正认识\"夫子欲寡其过而未能也\"一句，便有望成为古之学者为己的上达君子。", keyPoint: "为政、修身、教育" },
  { id: 473, chapterId: 14, order: 26, original: "子曰：“不在其位，不谋其政。”曾子曰：“君子思不出其位。”", translation: "孔子说：“不在个职位上，就不去谋划那个职位上的政事。”曾子说：“君子所思虑的不越出他的职权范围。”", commentary: "①不在其位，不谋其政：不处在那个职位，就不考虑那方面的政事。位，职位、位置；谋，谋划、考虑；政，政事。\\n②君子思不出其位：君子思虑不超出自己的职位范围。思，思考；出，超出；位，本分、职分。语出《易·艮卦》象传\"兼山，艮，君子以思不出其位\"，曾子借以解释孔子之语。\\n③在上位不陵下，在下位不援上：语出《中庸》，谓处上位不欺凌下位，处下位不攀附上位。正己而不求于人，则上不怨天、下不尤人。\\n④素其位而行：语出《中庸》，安于自己当下的位置而行其事，不越位、不僭分。\\n---\\n\\n【解读】本章历史上有两种理解：一说\"子曰：不在其位，不谋其政\"与\"曾子曰：君子思不出其位\"当分作两章；一说应合为一章。自朱熹以后多取后者，因为孔子此语在泰伯第八已经出现过，此处无必要重复，而曾子引《易·艮卦》象传来解释何谓\"不在其位，不谋其政\"，义理一致，合则文从义顺。本章即采用合为一章的读法。\\n\\n孔子之意在于：君子作为有道德追求的人，要清楚自己的本分。无论大政方针，还是具体职位所要求的日常事务，凡不在本职范围之内者，都不应过多参与。这符合为政无为而治、以道德表率自然引导的风格，与前章蘧伯玉的为政相承。心一旦向外求，老想着本分之外的事情，思路便偏，想法便脱离实际，所以必须安于本分。\\n\\n具体可从三个层面体会：其一，找准自己位置后，不过多干预同处他位之人的工作，如厨师不必总盯着服务员、销售不必总考量财务，管理上有共通处可以借鉴，但必须立足于本职工作，否则便荒废了自家事务；其二，作为下属不要老是不理解领导而妄谋其政，应设法理解、配合而非抱怨；其三，作为上级与家长，不必总想着下属或子女应该怎样，那些自有法律、道德、行为规范来约束，不必投入过多思虑。\\n\\n但此语不可教条化、狭隘化。\"在其位，谋其政\"，思想不出其位才是根本。陈成子弑简公，孔子沐浴而朝，因其曾为大夫，此类国际大事必当参与政策的制定与建言，这正是在其位谋其政，而非思出其位。天下大事并非与己无关，但如何去关心、如何去影响则有道，须建立在个人修为与道德修养提高的前提下，这才是君子的本分。\\n\\n表面上看，本章是对君子的限制，实际却是一种极严苛的要求：知道自己的本分、自己的定位，极为难能。人的身份不断变化——为子、为夫、为父，中年时上有老下有小——在身份切换中找出不变的本分，才是有所成就的关键。承前章\"欲寡其过而未能也\"之提醒，不应把过多精力耗散在本分之外，否则看得眼花缭乱，迷于细节而忘其本分，终成下达的小人。\\n\\n本章对今人最大的启示在于划定思虑的范围：不是想做什么就做什么，超出礼法便偏；而该做之事没有做好，同样是失位。君子当如《中庸》所言，在上位不陵下，在下位不援上，正己而不求于人，则上不怨天、下不尤人，素其位而行。时时自我反省，便知自己许多时候正在对别人的工作品头论足、偏离本分。以\"欲寡其过而未能也\"自警，从道、德、仁、义、礼这些不变的天理出发求索，过错自然日减，生活亦将日益顺遂。", keyPoint: "中庸、为政、教育" },
  { id: 474, chapterId: 14, order: 27, original: "子曰：“君子耻其言而过其行。”", translation: "孔子说：“君子把说得多做得少视为可耻。”", commentary: "①耻：以……为羞耻。君子是有羞耻心的人，故以言行不符为耻。\\n②其言而过其行：言辞超过他的行为。\"而\"在此作\"之\"字解，即\"其言之过其行\"；日本流传的《论语》版本正作\"耻其言之过其行\"。\\n③过：超过、超出。言过其行，即说得多、做得少。\\n④言顾行，行顾言：语出《中庸》，说话要顾到行动，行动要顾到所说的话，即言行一致。\\n⑤讷于言而敏于行：语出《里仁》\"君子欲讷于言而敏于行\"，言语谨慎而行动敏捷，与本章意旨相通。\\n---\\n\\n【解读】本章意思明了：君子以说得多、做得少为耻。此义与里仁篇\"古者言之不出，耻躬之不逮也\"基本一致——古之贤德者不轻易说话，唯恐说出却做不到而蒙羞；《礼记》亦言\"有其言而无其行，君子耻之\"，讲得出道理却没有与之相配的德行，言行相矛盾，君子以此为耻；又与\"其言之不怍，则为之也难\"相通，说话大言不惭，则很难指望他做得到。其内在道理正是《中庸》的\"言顾行，行顾言\"，以及\"敏于行而讷于言\"。人天生口齿伶俐，想到什么就说什么，思想可以很活跃，但行为却要受物质条件与个人能力的种种局限，故须多做事、少空谈。\\n\\n本章与前章\"君子思不出其位\"结合极紧：思出其位，言辞必然与行为相矛盾——所说之理自己尚且做不到，别人会对道理、对人生疑，自己也会惭愧，这正是不在其位而谋其政的结果。谋本有商议、言谈之意，不是本分的事便不去妄说。国家明令不得妄议大政国策，也是此理：完全不了解而凭臆想发论，便是胡说，说话不负责任，如何做得好事？\\n\\n关于\"而\"字，朱熹有一种独特的解法：作并列解，即\"耻其言，同时过其行\"——以言为耻、以行为过。耻者\"不敢尽\"之意，有止叫作耻，即知止，说话不过分；过即使之过、使之超过，实即敏于行的意思。此解虽为后世考据家所反对，认为把言行解作平行关系近于曲解，但亦自有其道理。\\n\\n古之学者为己，修行下手处不外言语、行为与心念三者。心念决定言行，而心念最难观察，故只能观其言辞与行为：以言为耻，时时自察是否说错话、说错即羞；以行为过，观己身所为有无过错而加修正。蘧伯玉\"欲寡其过而未能也\"，其过便须从行为与心行上去看，心念之动广义上也是作为。孔子之道一以贯之，言行亦当一贯，言行不能一贯便非君子。\\n\\n有德者必有言，故要把道理讲得清楚明白，讲不明白说明知之未深；但有言者不必有德，能讲出来不等于做得到，做到方为有德、方为君子、方能无愧于心而坦荡愉快。要达到言行一致、一以贯之于道，下一章的\"仁者不忧，知者不惑，勇者不惧\"正是追求所在。从日常入手，不断观察思考，不胡思乱想，思不出其位——先找到自己的位，安顿自己的心，需慢慢求索。本章对今人最大的启示即在于：平常的修行就是修正自己的言语与行为，时时观察二者是否一致、是否合于道。", keyPoint: "中庸、言行" },
  { id: 475, chapterId: 14, order: 28, original: "子曰：“君子道者三，我无能焉：仁者不忧，知者不惑，勇者不惧。”子贡曰：“夫子自道也。”", translation: "孔子说：“君子所循的三个方面，我都没能做到：仁德的人不忧愁，智慧的人不迷惑，勇敢的人不惧怕。”子贡说道：“是老师对自己的描述。”", commentary: "①君子道者三：君子之道有三。道，君子修身之道；三，指仁、知、勇三者。\\n②我无能焉：我都没有能够做到。无，没有；能，能够；焉，于此。系孔子自谦之辞。\\n③仁者不忧：仁德的人不忧愁。仁者乐天知命，甘于天命，所行皆合乎本心，故无忧虑。\\n④知者不惑：明智的人不迷惑。知，同\"智\"。不为外界纷纷杂杂的信息所扰乱，不被似是而非的道理所迷惑。\\n⑤勇者不惧：勇敢的人无所畏惧。明知世上有不合道之人事，仍以勇气加以匡正，而内心无所畏惧。\\n⑥夫子自道也：夫子是在说他自己。道，言说。子贡谓孔子所说的正是孔子自身，谦称\"无能\"而已。\\n---\\n\\n【解读】君子之道有三：仁、知、勇。此语在子罕第九篇中已经讲过，但那处较为简略，只有\"仁者不忧，知者不惑，勇者不惧\"，既无\"君子道者三，我无能焉\"的自谦，也无子贡\"夫子自道也\"的总结。本章结构更为完整：一方面孔子自谦德行尚有所不足，另一方面勉励后学，明确指陈君子修行的方向及其达成的结果。\\n\\n不忧、不惑、不惧皆为结果，其根源在于君子首先是一个仁者、一个知者、一个勇者。三者既可并列，又互相联系，归根结底是因为君子在道，故曰道者。道显现为仁、显现为知、显现为勇，皆是得道之德，修道有所得，才会显现出种种能力。\\n\\n仁者何以不忧？仁者乐天知命，甘于天命，深知自己所行皆在道中、合乎本心，便无可忧虑。人之所以有忧虑，多因不知本心、不知本位，不明白何事当做、何事不当做。若知凡事皆有规律，只需尽自己本分，不言过其行、不思出其位，便无扰无忧。知者何以不惑？不惑在于有智慧，不被外界纷杂的信息所扰乱，不被种种似是而非的道理所迷惑。勇者何以不惧？世道上毕竟有不合道之人、不合道之事，须想尽办法匡正之、帮助之。天下无道之时，君子亦须自我保护，危行言逊，正道直行而言语谨慎、安守本分，然其心无所畏惧，因为深知天道如何。\\n\\n子贡说\"夫子自道也\"，意谓孔子所言正是其自身。孔子自谦\"我无能焉\"，而亲近他的弟子们都认为他确实做到了，否则不会如此倾心追随。这与蘧伯玉的使者说\"夫子欲寡其过而未能也\"异曲同工——皆为谦辞，事实上他们都在不断减少自己的过犯。君子乾乾，天行健，君子以自强不息，依道而行永无止境，永远都在精进途中而不自满，但行进之中并无忧愁思虑，而是无所畏惧、无所疑惑、不为自身担忧。\\n\\n三者既各自独立又互相贯通：仁者不忧，因其有智慧勇气；知者不惑，因其是仁者，无所挂怀，如局外人般客观看待一切，又具直面不如意事的勇气；勇者不惧，因其心怀天下而无自私之牵绊，又不为外人与私心杂念所惑。三者合起来就是道。故当以此自省：有忧愁，说明仁德不够；有疑惑，说明智慧不足；有所畏惧，说明勇气未充。只要思不出其位、在其位谋其政，把本分事做好，一心通达仁义，君子上达，便能渐次靠近仁者、知者、勇者，成就各自心中最伟大的事业。对今人的启示在于：道理不明时，当向古圣先贤请教其行迹，然不可机械照搬——环境与挑战的形式或有差异，而规律与道理亘古不变，无为法共通，有为法在显现上可有差别，透过现象看本质，圣人之道亦是今人可行之道。", keyPoint: "仁德、教育、知命" },
  { id: 476, chapterId: 14, order: 29, original: "子贡方人，子曰：“赐也贤乎哉？夫我则不暇。”", translation: "子贡议论别人。孔子说：“你端木赐就什么都好吗？我就没有这种闲暇（去议论别人）。”", commentary: "①方人：评论别人的长短。\"方\"约有三解：一作\"谤\"，指说别人的坏话、评说他人长短；二作\"比方\"，拿自己与他人对比；三指直言不讳地当面批评别人的不是，希望其改正。重点在\"人\"字，即其他人，说明子贡眼光向外，盯着的是别人。\\n②赐也贤乎哉：端木赐你果真贤良吗？赐，子贡之名。语气轻松幽默，并非尖酸刻薄的讽刺。\\n③贤：亦可通假作\"闲\"，即闲暇。孔子借此讽示子贡很有空闲去管别人的事。\\n④夫我则不暇：我就没有这样的闲工夫。夫，发语词；暇，闲暇。孔子自谓整日忙于修身，无暇评人。\\n⑤君子不器：君子不局限于一器一用。器，器皿、器具。\\n⑥瑚琏：宗庙祭祀所用的贵重器皿。孔子曾以瑚琏喻子贡，谓其为国之大才而犹是器，未达君子之境。\\n---\\n\\n【解读】上一章孔子自谦\"君子道者三，我无能焉\"，子贡说那是夫子的自我写照。本章紧接着讲到子贡方人的事。子贡喜欢评说他人长短，\"方\"字可有谤、比方、当面批评等多种合理解释，总之其心思多放在别人身上。\\n\\n孔子没有直接批评子贡，而是幽默地说\"赐也贤乎哉？夫我则不暇\"——你很有闲暇去管别人，而我一天到晚没有闲工夫。孔子并非无所事事，他忙的是把自己做好：向着君子的方向，从不能到能，眼光向内，不在其位不谋其政，在自己的本位上考虑自己该考虑的事。蘧伯玉尚且\"欲寡其过而未能\"，自己也不例外。古之学者为己，为学修行的目的全在使自己成为更好的人，如此自然能影响、帮助他人；子贡在孔子眼里则近于今之学者为人。\\n\\n但也不应把子贡当作典型反面教材。见贤思齐，子贡很了不起，他擅长敏锐地观察别人的优点与缺陷，这是其天性所在。孔子实是希望他百尺竿头更进一步，把言语与观察上的天才更加聚焦，认识通往圣贤之道该怎么走，不要满足于做一个优秀的人才。孔子评子贡是个器——瑚琏那样的贵重之器，国之栋梁，但君子不器，他尚未达到君子的境界。\\n\\n本章正点明了子贡何以未达圣贤之境：在于方人。他以一生的言行为我们作出表率——哪怕财富再多、辩才无碍、能影响国际大局，只要还有一丝心牵挂于他人，没有精神内守，不把全部精神贯注于成就自我，不能像颜回、原宪那样不受外物牵绊，一箪食、一瓢饮、在陋巷，人不堪其忧而回也不改其乐，便不能算究竟。我们要学孔子、学颜回这些最好的榜样；学子贡的豁达大度、机智聪明，但不学他的方人。评较别人短长虽是穷理尽性、见贤思齐、见不贤内自省之事，但专务于此便心逐于外，对自己的省察就疏阔了。\\n\\n孔子启示子贡：当全身心安于本位。修为到一定程度、突破小我之后，看到别人其实就是看到自己——别人的缺点就是自己的缺点，别人的优点就是自己的优点。今人有\"你遇到的所有人其实都是自己\"之说，或为过去的自己、或为现在的自己、或为未来的自己，甚有道理。人性共通，若把大量精力放在与别人比较上，便流于片面、有局限、不通达而少智慧，容易迷惑。要做到仁者不忧、知者不惑、勇者不惧，核心正如《大学》所言：自天子以至于庶人，一是皆以修身为本。身体不长在别人身上，眼光一定要向内，这正是本章对我们最大的启发。", keyPoint: "仁德、修身、学习、忧乐、教育、礼乐" },
  { id: 477, chapterId: 14, order: 30, original: "子曰：“不患人之不己知，患其不能也。”", translation: "孔子说：“不担心别人不知道自己，只担心自己没有能力。”", commentary: "①不患人之不己知：不担忧别人不了解自己。患，忧虑、担心；不己知，倒装句，即\"不知己\"，不了解自己。\\n②患其不能也：只担忧自己没有能力。其，指自己；不能，没有能力、没有水平。\\n③人不知而不愠：别人不了解自己而不恼怒。愠，恼怒。语出学而第一第一章，与本章同一道理。\\n④学而不厌，诲人不倦：认真学习而不厌倦，教导别人而不知疲倦。语出述而第七，孔子自谦\"何有于我哉\"。\\n⑤古之学者为己，今之学者为人：古代学者为修养自己而学，今之学者为向人显示而学。语出宪问第十四。\\n---\\n\\n【解读】本章的道理在《论语》中已反复出现：学而第一第一章的\"人不知而不愠，不亦君子乎\"，学而篇的\"不患人之不己知，患不知人也\"等，皆与此相通。别人不了解自己，不为此生气，只要有真才实学，早晚会被人了解。重点始终落在自己身上，而非别人身上。从这些不同话语中表现出的相近意思可见，孔子的道确是一以贯之的。而要了解别人，关键仍在于提升自己的能力水平，把自身认识透彻、对人性练达，方能推己及人，找到彼此共通之处，这与\"其恕乎？己所不欲，勿施于人\"的道理相通。\\n\\n本章紧承子贡方人一章之后，编纂者之意意味深长：前面刚委婉批评子贡眼光向外、评人长短，说自己没有这闲工夫，那么功夫用在哪里？正在\"不患人之不己知，患其不能也\"。孔子所忧的\"能\"，是述而篇\"学而不厌，诲人不倦\"之能——认真修学而不厌倦，把道理教给别人而不生厌烦，以对待自己的心对待他人，孔子自谦\"何有于我哉\"。第二十八章\"君子道者三，我无能焉\"中的\"能\"同此。在子贡看来，孔子已经做得圆满了，所以子贡说\"夫子自道也\"；但孔子自己看来仍在不断精进，这正是他的\"患其不能\"。\\n\\n此处\"其\"字可有多种排列组合式的读法：或谓不担心别人不了解我自己，只担心自己没有能力；或谓不担心别人不了解他自己，而担心自己没有能力；或谓不担心别人不了解他自己，只担心他没有能力；或谓不担心别人不了解我自己，只担心别人没有了解我的能力。各种读法都各有道理，只是修行的路径随之不同。孔子之道的真义是：不担心别人不了解我，只担心自己没有能力——正因为没有能力，别人才不能知道我；若我有能力，别人自然知道我，即使他不知道，我内心亦是自足满意的。这又回到\"古之学者为己，今之学者为人\"的分判。\\n\\n学《论语》必须前后贯通，同一篇往往围绕一个主题反复申述，从不同角度、不同层面把道看得清楚，这正是圣人的苦口婆心。本章对今人的启示在于：学习君子之道，要时时担忧自己尚不具备仁者不忧、知者不惑、勇者不惧这样的大能，并为此不懈努力；夫我则不暇，没有多余的功夫去关注那些与自身、与大道、与仁义无关的事情。", keyPoint: "仁德、学习、忧乐、教育、知人" },
  { id: 478, chapterId: 14, order: 31, original: "子曰：“不逆诈，不亿不信，抑亦先觉者，是贤乎！”", translation: "孔子说：“不预先怀疑别人欺诈，不凭空臆想别人不诚信，却能先行察觉，这样的人才是贤者啊。”", commentary: "①不逆诈：不预先怀疑别人欺诈自己。逆，本意是别人未至而预先出迎，引申为预先、预知；诈，欺诈。\\n②不亿不信：不随便臆测别人不诚实。亿，通\"臆\"，臆测、推断；不信，一方面指别人不诚实，一方面指别人不信任自己。\\n③抑亦：连词，但是也。抑，转折连词；亦，也。如《隆中对》\"非惟天时，抑亦人谋也\"用法相同。\\n④先觉：预先觉察。觉，觉察。既可指觉察别人的欺诈与不诚信，也可解作自己比那些诈、不信之人先行觉悟。\\n⑤是贤乎：这样的人是贤人吧。是，此、这样；贤，贤能；乎，感叹语气词。\\n⑥君子可欺也，不可罔也：君子可以被人欺骗，却不能被愚弄迷惑。语出雍也第六\"宰我问井有仁焉\"章。\\n⑦明察秋毫：连秋天鸟兽新生的细毛都能看清，形容观察入微、明辨事理。\\n---\\n\\n【解读】本章又谈君子知人，与前几章联系紧密。前面曾讲到与季康子论卫灵公，谓其不败亡在于善用贤人，可见知人善任是执政者的重要能力。那么贤明之人如何看待他人？孔子提出三点：不逆诈、不亿不信，而能先觉。\\n\\n\"不逆诈\"，即不预先假设别人是来欺骗自己的，是一种无罪推定——先假定所有人都是好人，不用怀疑的眼光看人，不预设对方有阴谋。\"不亿不信\"，亿通臆，即不预先臆测别人的品格；逆诈是就\"你来骗我\"而言，不信则更多关乎对方本身的特质。二者相合，即《礼记》所谓\"君子不先人以恶，不疑人以不信\"：不预先设定别人是坏人，不预先想象别人要欺骗自己。世界上确有坏人，但更多的是好人一时鬼迷心窍做了错事；人做坏事往往有目的，并非为坏而坏。反观世人，自己欺诈，便先假设别人也欺诈；自己不诚信，便总预测别人不诚信——这正是小人的心态。真正的贤人、圣人，对于生活在欺诈与不信之中、连自己都不相信的人，是心怀哀悯的。\\n\\n\"抑亦先觉者\"，然而也能预先觉察。此\"先觉\"可从两方面理解：一是对别人的欺诈、不诚信行为事先发觉；二是自己本就比那些诈、不信之人先行觉悟，凡事能事先知晓，不只限于别人欺我之事。人之所以能不逆、不亿，正因为自己不诈、不疑：自己至诚，因诚生明，自然坦然坦诚。首先是不欺骗自己——欺骗别人本质上就是欺骗自己；要骗过别人，先要骗过自己，而一味自我欺骗，最终便不知何为真实，沉溺于谎言虚伪之中，永在迷惘，谈何觉悟。\\n\\n此章可与雍也第六\"宰我问井有仁焉\"章参看，孔子曾说\"君子可欺也，不可罔也\"：君子可以当面被人欺骗，会出于仁心包容容忍，不做有罪推断，但别人骗不过他，他不会陷入别人的陷阱。你可以暂时欺瞒他，甚至向他借钱应急，他也肯借；但一旦他发觉受骗，终会识破，因为君子不是傻子。他只是预先不假设你是坏人，推己及人——自己是诚实的人，便相信绝大多数人诚实，不因少数坏人而带着有色眼镜看待所有人，弄得自己紧张兮兮、不得坦然。同时，贤者真有受骗之事时又能事先觉察，因为他通达人性，知道诚实是什么模样，也知道人撒谎时在细微之处有何表现，故能明察秋毫。\\n\\n本章对今人最大的启示在于：不要老是怀疑别人，而出发点则是自己不要总想着骗人——想着骗人，就会害怕被人骗。自己不诈、无不信，首先做一个诚恳、诚实的人。", keyPoint: "知人、诚信" },
  { id: 479, chapterId: 14, order: 32, original: "微生亩谓孔子曰：“丘何为是栖栖者与？无乃为佞乎？”孔子曰：“非敢为佞也，疾固也。”", translation: "微生亩对孔子说：“您为什么如此奔波忙碌呢？不是为了显示您的才辩吧？”孔子说：“我不敢显示我有才辩，只是讨厌那种顽固不化的人。”", commentary: "①微生亩：人名，生平无定论。汉朝有人认为即公冶长第五中孔子所评\"孰谓微生高直\"的微生高，一位古道热肠的隐士；也有说即尾生晦。其年长于孔子且与孔子相熟，故直呼孔子之名\"丘\"。\\n②栖栖（xī）：忙忙碌碌、奔波不息的样子，如鸟儿寻找栖息之木而尚未安稳。\\n③无乃……乎：恐怕、难道不是……吗，表推测的语气。\\n④为佞：逞口才、做说客，用言语去讨好取悦别人。\\n⑤疾固也：有两解。一解\"疾\"为毛病、缺点，谓孔子自谦好为人师，见君主有过错便想纠正，此\"毛病\"根深蒂固；一解\"疾\"为动词\"痛恨\"，即痛恨那些固执偏狭之人，如愚公移山\"汝心之固，固不可彻\"。\\n---\\n\\n【解读】本章借微生亩与孔子的对答，显现孔子的言行与待人之态度。微生亩直呼孔子之名\"丘\"——古人直呼其名只能是长辈对晚辈，可见他年长于孔子且彼此熟悉。\"栖栖\"形容孔子离开鲁国后四处漂泊，如鸟儿寻找栖息之木，一直寻求贤明的君主，希望其接受复礼、仁政的理念，使国家兴旺、世道重归太平。微生亩于是问道：你为什么这样忙忙碌碌？难道是想显示自己的口才、用言语去取悦于人吗？孔子谦虚地回答说：\"非敢为佞也，疾固也。\"不论\"疾固\"取何种解释——或是自谦自己好为人师、见错必纠的根深蒂固的毛病，或是痛恨固执偏狭之人——孔子都是在自述己志。\\n\\n这体现了儒家积极入世的精神：以自身的德行与才干造福天下，而非隐藏起来。自己有能力、是\"不逆诈，不亿不信，抑亦先觉者\"那样的贤人，既是先觉者，又怎能不带动后觉之人？后知后觉者若无人用言语敲打、引导，何时才能觉醒？正如近代鲁迅先生以笔为刀，刺入麻木者的身躯使其警醒，虽痛却是救命。孔子、孟子及历代有志之士皆一脉相承，其用心并非为了显示自己、求取高官厚禄，更不是用口才讨好君主，而是真正为国家、为人民体现自身的价值。他们时刻担忧的，恰是自己能力不足、不能做到仁、智、勇——患其不能。\\n\\n微生亩或许是了解孔子的，他借这样一个直言不讳的问题，让孔子自述其志；而这样近乎不礼貌的问话，也只有年高德劭、什么都不在乎的人才能问得出，不失赤子之心，并无恶意，只是出于好奇。孔子则谦虚而尊重地作答。\\n\\n本章对今人的启示在于：要时刻观察自己行为的动机——是为了做一个讨好别人的佞人、别有所求，还是对不义之事深恶痛绝、要做真正正义而有价值的事？无论学习微生亩的恬退——觉得世道不可救药便独善其身、做好自己，还是学习孔子明知不可为而为之、尽心尽力而无怨无悔、功成不必在我的大无畏精神，都能做得很好。两者本质一体、互相理解、互相成就：正因有人不图功名、甘于默默无闻，才更显出那些倾尽才德为大家奉献者的珍贵。这两种人都值得学习。", keyPoint: "义利、仁德、教育" },
  { id: 480, chapterId: 14, order: 33, original: "子曰：“骥不称其力，称其德也。”", translation: "孔子说：“对于千里马不是称赞它的力气，而是要称赞它的品德。”", commentary: "①骥：善马、良马，即世人所谓千里马，善跑善驰。\\n②称：称道、赞美。全句意为：称千里马为骥，不是赞美它的力气，而是赞美它的德行。\\n③驽马：奔跑迟缓、资质较差的马。\"驽马十驾，功在不舍\"，即使慢马，只要坚持不懈地努力，也能走得长远。\\n④鸣和鸾、逐水曲、过君表、舞交衢、逐禽左：《周官》所记善马之德——驾车时与同驾之马配合有序、铃声和鸣，知水沿岸而行，经过君表缓步慢行、不失威仪，驰于集市与人众之地从容有度，打猎时能居禽兽之左以利车右攻击等。\\n⑤三达德：仁、知（智）、勇。\"君子道者三\"，仁者不忧，知者不惑，勇者不惧，此为人所当称道的德行。\\n---\\n\\n【解读】本章表面在讲马，实则借良马比喻人才。孔子说称千里马为\"骥\"，赞的不是它力气大、跑得快，而是它驯良有德的品性。驽马虽慢，坚持努力亦可致远；骥虽能千里，若无德行便不足称道。世人称马好，往往只从外在气色、力量着眼，因为这些容易被人认知；而马的内在气质则很难发现，需要养马、调马之人细心观察、与之互动，加以培养，使其天分得以展现。正如韩愈所言\"千里马常有，而伯乐不常有\"，好马若无识者，食不饱、力不足，才美亦不外见。马如此，人亦然——身强力壮、天赋过人并不值得夸耀，真正值得称赞的是内在的德行。\\n\\n良马之德，《周官》有详细记载：鸣和鸾，指驾车时与同驾之马协调配合，铃声清脆有节奏，不暴躁、不争功。春秋战国时马凳尚未发明，骑马不便，出行皆赖骖乘、驷马之车，故合群协作尤为重要，独行侠式的马无法驾车。逐水曲、过君表、舞交衢、逐禽左，则言其知水沿岸、见君缓步、集市有威仪、狩猎善配合。这些都说明善马之德重在协和与分寸。推之于人，所当称道的正是《中庸》所讲的三达德——仁、知、勇。\\n\\n此章更与为政相通。驾驭马匹不可单凭外力，为政更不能用暴力，不能凭借外在条件耀武扬威。内在修养充足，德行具足，智仁勇皆备，则\"为政以德，譬如北辰，居其所而众星共之\"，自能感召他人，而非用力气去压服。凭武力侵略他人者，绝不会得到好的结果。\\n\\n本章于今人的启示是：无论对人、对己、对国，都不可只看重外在的气色与力量，而应看重内在的品质与德行。表里相称，由内而外，方为君子立身之道。", keyPoint: "中庸、为政、仁德、教育" },
  { id: 481, chapterId: 14, order: 34, original: "或曰：“以德报怨，何如？”子曰：“何以报德？以直报怨，以德报德。”", translation: "有人说：“用恩德来报答怨恨怎么样?”孔子说：“用什么来报答恩德呢?应该是用正直来报答怨恨，用恩德来报答恩德。”", commentary: "①报：报答、回报。\"以德报怨\"即以恩德回报怨恨。\\n②直：正直、直道。此处\"直\"既指本心如何想便如何做、爱恨分明的直，也含圣贤境界中不挂怀于心、自然化解怨恨之义，关键在不虚伪造作。\\n③德：此处偏指恩德、德行，是道的累积。得道之后德行始终如一，故以德报德，德行是持久的、永恒的。\\n④亲不失其亲，旧不失其旧：亲近的不失去亲近，故旧的不失去故旧，喻恩德当永远铭记、终生报答。\\n⑤知恩报恩：对父母生养之恩、老师教诲之恩当以恩德相报。天、地、君、亲、师并尊，尊师重道，方是真正的以德报德。\\n---\\n\\n【解读】本章非常重要，体现了儒家与道家思想根源虽一、展现形式与侧重点却不相同。以德报怨，近于《道德经》\"报怨以德\"，是道家的高境界：德为道的累积，既已得道，则无论外境如何，对人都始终如一，如太阳不因天气而改其光热；基督教\"人打左脸，伸右脸\"亦是此意。但对于尚未成就的普通人而言，这是几乎做不到的。若内心认定以德报怨是对的，自己却做不到，强求之下便添一层作伪，反而不直不真诚；本已受怨，又自怨，便成了以怨报怨。以怨报怨是未学之常态，往好方向发展，则可如孔子之以直报怨。\\n\\n以直报怨的\"直\"，有深浅两层：一是本心如何想便如何做，别人害我我亦回应，爱恨分明，天然近于义；一是已达圣贤境界，别人对我不好亦不必伤害，心中自然消解怨恨、不复挂怀。两种都以直面本心为前提，绝不虚伪造作。怨当速了，无论以何方式了结，报过即止，勿再纠缠，所谓\"不打不相识\"，怨消之后或可为友；唯有德行永远不能忘，必以恩德相报。父母生养之恩、老师教诲之恩皆难报答，而真正明师之恩犹在父母之上——父母只是把我们带到世间，明师却让我们明白人生的价值与意义。天、地、君、亲、师同尊，故尊师重道，才是以德报德。\\n\\n孔子并非教人简单地以怨报怨、以德报德。直之一字，正是修行的方向与目标。我们所以有恩怨，实因有\"小我\"；若达高境界，则怨亲平等，知\"恩生于害，害生于恩\"。见有怨便强求以德报之，心存作伪，即是人我是非尚未消解，报后仍会挂怀后悔，非君子坦荡荡之境。怨恨当以正直之心忘却，德行则当永远以恩德相报。\\n\\n本章的启示在于：依老师教诲而修，成为一个真正的大人，此即以德报德；面对世间不平，则以直报怨，以正直回报。心平则天下早晚太平。", keyPoint: "君子小人、教育" },
  { id: 482, chapterId: 14, order: 35, original: "子曰：“莫我知也夫！”子贡曰：“何为其莫知子也？”子曰：“不怨天，不尤人，下学而上达。知我者其天乎！”", translation: "孔子说：“没有人了解我啊！”子贡说：“为什么没有人了解您呢？”孔子说：“不埋怨天，不责备人，下学人事而上达天命。了解我的大概只有天吧！”", commentary: "①莫我知：没有人了解我。\"莫我知\"为宾语前置，即\"莫知我\"。\\n②尤：责怪、怨恨。\"不怨天，不尤人\"意为不怨恨上天、不责怪他人。\\n③下学而上达：下学人事，上达天理。向下通达人事、向民众广泛学习，向上通达天道。\\n④天：此处不专指神明之天，更指义理之天、无形大道。故\"知我者其天乎\"，意即理解我的只有道了。\\n⑤一以贯之：孔子教曾参\"吾道一以贯之\"，曾参转述为\"夫子之道，忠恕而已矣\"，由一而二，可见当时尚未完全领悟。\\n---\\n\\n【解读】自司马迁而下，董仲舒、刘向诸先贤皆认为此章系孔子晚年之叹。其时孔鲤、颜回、子路相继离世，鲁哀公十四年又获麟而伤，孔子物伤其类，发此浩叹。孔子一生积极向上，自幼丧父、少时丧母，从未消极颓唐，正如其所言：不怨天，不尤人，下学而上达。向下与穷苦大众为伍，教学一视同仁、因材施教，广泛学习世间真理，进而通达天道，这是他毕生切实去做的事。\\n\\n然而晚年欲传道统之时，嫡传真传的颜回早夭；子贡虽优秀，尚欠火候；曾参受教\"吾道一以贯之\"，出而转述竟成\"忠恕而已矣\"，一变为二、无极化为两仪。夫子在世时竟无人能完全承其道统。曾参晚年虽达高境，其弟子却多有偏离，流于谨言慎行之末节，失却夫子时的豁达洒脱；此后数百年儒家不为人理解，直至汉朝董仲舒复兴儒学，方得再见夫子本来面目。\\n\\n孔子此叹并非消极自伤，而是借机点醒子贡——这句话就是说给他听的：你虽优秀，却并不完全了解我。子贡聪慧，当即发问，孔子遂借机传其心学：不怨天，不尤人，不要再评人长短、论人是非，自我修行尚且时间不够。君子所为，是悬崖撒手、自肯承当，人生是自己的，怨天尤人皆是偏颇。既要无怨无尤，还要积极做事，其要即在下学而上达。欲知天道、仁义、天理，离不开人间的学问；理上通达而事上绊脚，便是理未真通。真正最基层的人拥有最广大的智慧，虽缺理论总结，却于解决实事中积累真实不虚的智慧，故须虚心广泛地向他人学习。\\n\\n下学的目的在上达，若陷入下学仅为个人利益与交换，便是小人下达而非君子上达。此章之天，是义理之天、无形大道，故\"知我者其天乎\"实含孔子向子贡默默道别之意。其对今人的启示在于：念念不忘发心，学\"古之学者为己\"，成就自身的知、仁、勇。", keyPoint: "学习、教育" },
  { id: 483, chapterId: 14, order: 36, original: "公伯寮愬子路于季孙。子服景伯以告，曰：“夫子固有惑志于公伯寮，吾力犹能肆诸市朝。”子曰：“道之将行也与，命也；道之将废也与，命也。公伯寮其如命何？”", translation: "公伯寮向季孙氏控诉子路。子服景伯把这件事告诉了孔子，说：“季孙氏已经被公伯寮迷惑了，我的力量还能让公伯寮的尸首在街头示众。”\\n孔子说：“道将要实行，是天命决定的；道将要被废弃，也是天命决定的。公伯寮能把天命怎么样呢？”", commentary: "①愬：同\"诉\"，进谗言、毁谤。\\n②肆：陈尸示众。周礼规定，犯重罪者陈尸示众，大夫陈尸朝堂，庶民陈尸市场，以示惩戒、儆诫众人。\\n③市朝：市场与朝堂。\\n④命：此处指义理之命、天命。孟子曰\"莫之为而为者，天也；莫之致而至者，命也\"——非人力所为而自然如此者是天，非人所招致而自然到来者是命。\\n⑤隳三都：鲁定公年间孔子为司寇，主持拆毁三桓违制城墙的变革，子路参预其事。\\n---\\n\\n【解读】前一章孔子讲天，本章则讲命。公伯寮在季孙面前毁谤子路，子服景伯告知孔子，并表示自己有力量杀掉公伯寮、陈尸市朝。此章背景在鲁定公年间孔子为司寇、季桓子当政之时。季桓子起初支持孔子隳三都、削三桓之权，后因孟孙氏不肯隳郕，季桓子、叔孙氏反悔，又受齐国女乐，鲁定公三日不上朝，祭肉不分于大夫，孔子遂去鲁周游。公伯寮乃鲁国一个小官，在隳三都、子路实任其事之时，到季桓子面前进谗言，实为干扰变革。子服景伯为孟孙氏贵族，视孔子为师，故请命于孔子。\\n\\n孔子答以\"道之将行也与，命也；道之将废也与，命也\"，正道能否推行，非人力所能决定，而是由时代与命运决定的。若事能成，公伯寮再毁谤也无用；若事本不成，则与其毁谤无关。此与\"天生德于予，桓魋其如予何\"同旨。对于天与命的理解，孔子何其深刻：一般人遇事不顺，总归咎于某个人、某件事，孔子却不如此。他并未像子服景伯那样把矛头直指公伯寮，而认为冤有头债有主，冤仇不在某一个人身上，而在整个世道——公伯寮只是一个代表，子路做事不圆满、得罪了人，才招来毁谤。故当以直报怨，而非以怨报怨。公伯寮之来，是子路的命，也是孔子的命，此即\"莫之致而至者\"的不期而至。\\n\\n一般人无论是公伯寮还是子服景伯，皆是士大夫一流人物，仍不能脱离命运的影响；子路、孔子自己亦在其命运之中。但换一个角度看，若无孔子明知不可为而为之的努力，改变环境、恢复圣贤指出的光明大道，则文化早断，既无孟子，亦无千年文化的积淀。故此章于今人最大的启示在于：知命而不认命，学习圣贤，通过自己的努力把命运掌握在自己手上。最终做到什么程度虽非自身所能影响，但只要努力过，便无怨无悔。", keyPoint: "处世、学习、教育、知命、礼乐" },
  { id: 484, chapterId: 14, order: 37, original: "子曰：“贤者辟世，其次辟地，其次辟色，其次辟言。”子曰：“作者七人矣。”", translation: "孔子说：“贤人逃避恶浊乱世而隐居，其次是择地方而住，再其次是避开不好的脸色，再其次是避开恶言。”孔子说：“这样做的人有七位了。”", commentary: "①辟：逃避、躲避。亦可读为\"开辟\"，指开创新局面，本章以逃避乱世之义为主。\\n②辟世：避开恶浊的社会而隐居。\\n③辟地：离开混乱的国家，择地而处，即\"乱邦不居\"。\\n④辟色：避开他人、特别是君王难看的脸色。\\n⑤辟言：避开难听的言语。\\n⑥作者七人：这样做的人已有七位。一说指微子篇所载伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连七位逸民；一说指孔子同时代的隐者，其中有留名者，亦有未留名者。\\n---\\n\\n【解读】本章紧承前章论命、再往前论天而来，讲的是贤者遭遇混乱世道时如何处世。贤人避乱，头一等是直接隐居，与整个时代无涉；次一等未逃得那样远，只是离乱邦、赴善地；再一等不看他人的难看脸色，己正而能察人，色不善则去；又次一等则避开难听的言语，己不言恶言，亦避他人恶语。孔子谓这样做的人已有七位，可见世道之坏。七人之说，通常认为实指微子篇所载七位逸民；亦有认为是指孔子同时代、或留名或未留名的隐者。两种说法皆可通。\\n\\n孔子一般不为人视为隐逸一派，但本章可见他对隐居并不排斥，其本人亦有\"道不行，乘桴浮于海\"之想。因为\"邦无道则隐\"，智者当分辨时世，先明哲保身。这并非消极，而是一种积极的等待，同时以自身言行作榜样，昭示世人不与混乱的世道同流。此外，\"辟\"亦可读为\"开辟\"：贤者辟世，是开辟一个时代；次一等影响一地之人；再次影响身边人的礼貌，待人接物和颜悦色；又次则谨持自身言行，此即\"有德者必有言\"。等次之别并非贤者本质有高下，而是各人境遇不同，由命运决定。结合上下文，仍以\"天下无道而隐\"之义为切当。\\n\\n真正的隐居，并不一定要遁入深山老林。如下一章的晨门，身任小吏而识见非凡，世道不了解他，他却在乱世中自我保全，何尝不是一种避世，此即大隐隐于市。本章所见的，是儒家的自由精神：先求个人品德达于一定境界，对时代无能为力时便避开，不受其影响，保持有用之身，其中仍隐含着积极的意味——自全其身，目的并不在己，而在整个世界世道；贤者欲开创一代新风，但要顺遂天命。\\n\\n于今人的启示是：无论积极入世还是消极避世，都只是手段，目的都在成就最高尚的道、最圆满的德行与自身的智慧勇气。避世同样需要勇气，要能顶得住他人的不解，尤其是亲人的压力。", keyPoint: "知命" },
  { id: 485, chapterId: 14, order: 38, original: "子路宿于石门，晨门曰：“奚自？”子路曰：“自孔氏。”曰：“是知其不可而为之者与？”", translation: "子路在石门住宿了一夜。早上守城门的人说：“从哪儿来？”子路说：“从孔子家来。”门人说：“就是那位知道做不成却还要做的人吗？”", commentary: "①石门：鲁国都城的一座城门，为外郭之门。古代城墙有内城、外郭两道门，石门为外门。\\n②晨门：负责清晨开启城门的看门人，亦管夜间关闭城门。\\n③奚自：从哪里来。\"奚\"为何处，此问看似寻常，实隐含着\"我是谁、我从何来、我往何去\"的深意。\\n④自孔氏：从孔家来。子路不报姓名而自陈孔门，见其对夫子之尊崇。\\n⑤知其不可而为之：明知行不通却仍坚持去做，此语后来成为对孔子一生的定评。\\n---\\n\\n【解读】此章是一则意味深长的故事。子路自外归来，夜宿于鲁国都城外郭的石门，清晨门吏问其来处。时间上有两种可能：一为鲁定公年间孔子为大司寇、隳三都之时，子路协助孔子政务，自外回都复命；一为孔子周游列国、到处碰壁之际，子路因故返都。若孔子已老而退隐洙泗，守门人便不会再如此相问了。\\n\\n晨门问\"奚自\"二字，实含深意。哲学的三大疑问——我是谁、我从哪来、我到哪去——其核心即在来处；来处最终即归途，你是谁又与你从哪来息息相关。晨门所问，近乎禅宗打机锋，虽儒者不事此道，然其意正是向子路讨教：你是什么人，你从何处来？子路答得毫不含糊：自孔氏。他不报姓名，只称孔门之人，生是孔门之人、死是孔门之鬼，可见其对夫子的尊崇，亦可见其办事奉命而行的身份。守门人遂下一断语：是知其不可而为之者与——这正是对孔子的赞扬而非讥讽。贤者避世，知不行即不为，省却气力；而孔子明知其事难成，只因合于道、合于义便一定要去做，别人都不做，就由我来做。贤者善全其身，圣人则知其不可而为之。\\n\\n这位晨门实为深藏不露的高人，身任小吏而大有水平，大隐隐于朝。他了解孔子，一句问话也寓有教育之意：你不算好时辰，夜宿城郭之外，可知自己从何而来、当回何处？子路答\"自孔氏\"，清楚明白，正是真诚、正是直，圣人的教导要达成的，不过是去其后天虚伪，复归先天本真。晨门此语亦为孔子在历史上定了论，今人形容孔子，仍不外\"明知其不可为而为之\"。\\n\\n圣人贤者由此可分四种：知可为而为之，如伊尹、周公；知不可而不为，如前章\"作者七人\"之伯夷、叔齐；知可而不为，如许由、巢父；知不可而为之，史上最著名者即孔子，并由此引导一代代圣贤。孔子自称\"无可无不可\"，只要道所当为，便为之。本章于今人的启示是：当知自己从何而来、根在何处，明其本心与去向；目标坚定，无论世人看来是否可行，人生终将有成，不虚此行。", keyPoint: "教育" },
  { id: 486, chapterId: 14, order: 39, original: "子击磬于卫，有荷蒉而过孔氏之门者，曰：“有心哉，击磬乎！”既而曰：“鄙哉，硁硁乎！莫己知也，斯己而已矣。深则厉，浅则揭。”子曰：“果哉！末之难矣。”", translation: "孔子在卫国，一次正在击磬，有一个挑着草筐的人经过孔子门前，说：“这个磬击打得有深意啊！”过了一会儿他又说：“真可鄙呀，磬声硁硁的，没有人知道自己，就自己作罢好了。水深就索性穿着衣服趟过去，水浅就撩起衣服走过去。”孔子说：“说得真果断啊！真这样的话，就没有什么可责问他的了。”", commentary: "①磬：古代石制打击乐器，状似钵盂，声音清越，孔子善于击磬。\\n②荷蒉：挑着草筐。蒉，竹木编制的草筐，荷蒉者当为亲自劳作的平民隐士。\\n③硁硁：击磬之声，亦用以形容人固执、倔强，一意孤行。\\n④莫己知也，斯己而已矣：没有人知道自己，那也就算了，做好自己便罢了。\\n⑤深则厉，浅则揭：出自《诗经·邶风》。厉，穿着衣服涉水；揭，撩起衣裳过河。比喻世道水深则索性不顾一切涉水而过，水浅则从容提起衣襟。\\n⑥果哉！末之难矣：一说\"果\"为果敢、坚决，\"末\"为无，\"难\"为问难、责难，谓其言已坚定如此，无法说服；亦有解\"难\"为难易之难、或解\"末\"为终了之意者，众说皆可通。\\n---\\n\\n【解读】此章文义虽有多处可作不同解释，但整体上是前面数章的总结，达到了一个小小的高潮。自\"子贡方人\"、孔子叹\"莫我知也\"，至\"贤者辟世\"，再至晨门称孔子为\"知其不可而为之者\"，所有信息至此汇于一处。故事发生在孔子周游列国居于卫国之时。磬为石制乐器，孔子善乐，曾言\"吾自卫反鲁，然后乐正，雅颂各得其所\"。一个背着草筐的隐士经过孔子门前，听出磬声中隐含着孔子的心事，便称其为有心人。他继而评道\"鄙哉，硁硁乎\"：一说讥磬声过于固执偏狭，一说从磬声中听出孔子对满世界硁硁然小人的愤懑，两解皆通。\\n\\n\"莫己知也，斯己而已矣\"，是说自己不为人所知，那就算了，做好自己便是。\"深则厉，浅则揭\"出自《诗经·邶风》，以涉水为喻：水深则连衣而渡，水浅则提裳而行——世道黑暗已不可救，便不必再顾礼乐衣冠，自渡而已；世道尚可挽救，则依礼而行，保全衣冠、兼济他人。荷蒉者借诗言志，说自己所以隐居，正是因为世道不可救、自救已足。孔子听人传述后，以\"果哉！末之难矣\"回应。此语诸解并通：或谓其言果断坚决，我已无法问难、无法说服他——他既不能说服我，我也不能说服他，彼此各守其道；或解\"难\"为难易之难，谓果能如此随境而应，则天下无难事；或解\"末\"为终了，谓凡事坚持做到底才是难的。\\n\\n此章最大的启示，在于见出孔子与避世隐者的不同。隐者贤人追求的是智慧与解脱，无惑于己，不为俗世所累；孔子在此之上更成为仁者，他爱这些硁硁然的小人，想要拯救整个世道。世道水深，他仍要提裳过河而不肯任衣裳沾湿，明知不可为而为之，此心便是慈悲。智慧与慈悲二者兼备而能互通、互相理解，才是真正的有心，而非无心之俗人、有心之圣贤之别。\\n\\n于今人而言，无论选择哪条道路，都要明确人生的目的；若有充分的智慧与德行，则无论走哪条路，人生都是光辉的，不会生活在焦虑与自我之中。", keyPoint: "仁德、教育" },
  { id: 487, chapterId: 14, order: 40, original: "子张曰：“《书》云，‘高宗谅阴，三年不言。’何谓也？”子曰：“何必高宗，古之人皆然。君薨，百官总己以听于冢宰三年。”", translation: "子张说：“《尚书》上说：‘殷高宗守丧，三年不谈政事。’这是什么意思?”孔子说：“不只是殷高宗，古人都是这样。国君死了，所有官员都各司其职，听从冢宰的命令长达三年。”", commentary: "①谅阴：天子居丧。一说指居丧时所住的茅屋，谅通\"梁\"，谓梁柱简陋的小屋。\\n②不言：此处指三年不发布政令、不议论政事，非谓一言不发。\\n③薨：古代诸侯、君主去世之称。\\n④总己：各司其职、各理己事。君薨之后，百官各尽其职，三年听命于宰相。\\n⑤冢宰：宰相。君主守丧期间，由冢宰代理国政，协调百官。\\n⑥殷高宗：即商王武丁，商汤第十世孙、商王朝第二十二代君主，盘庚迁殷后商朝中兴之主。\\n---\\n\\n【解读】此章承接前章的高潮，转而讲古代圣贤君主的榜样。子张读《尚书》，见\"高宗谅阴，三年不言\"而不解，孔子遂借其问阐明古礼。殷高宗即武丁，为商朝中兴明主，享国五十九年、寿近百岁，在位时四方诸侯来朝，善于用兵用人，孟子称\"武丁朝诸侯，有天下犹运诸掌\"。其父武乙去世后，武丁为之守孝三年。《尚书》所谓三年不言，或有些许夸张，实指三年不发布政令，与学而篇\"三年无改于父之道，可谓孝矣\"之义相通，都是表达对先人的怀念。\\n\\n孔子解释，为何定是高宗？古代君主皆如此。君王去世，世子继位，百官各司其职，却不向新君汇报，因为君主正在守丧，心情哀痛，无暇顾及政务；百官三年间听命于冢宰，由宰相代君治理国家，大政方针皆为先王所定，宰相以民主集中的方式协调百官，不再惊动守丧中的君主。孔子说这话时，心情想必十分沉重：这样的古礼，至其时代已基本无法延续。从武丁到孔子已历八百余年，许多优良传统虽载于典籍，子张却已不能理解，连礼制背后的道理也不明白。\\n\\n今人视之，君主三年不发布政令，令人疑惑：三年之中大事频仍，若宰相作乱或政务处置失当怎么办？古人却无此忧虑。他们相信一代代君主靠德行引导大众，宰相亦必称职，不会侵权乱来；先王政策的大方向无须改变，因为道没有变，三年不会出大的转折，纵有转折也是应当发生的，非一君之力所能左右。守丧三年更有深意：人三岁之前全然依赖父母，父母离去后，当以三年时间重新反省父母对我们的恩德，思考如何生活才不违背人的本质、不辜负父母的恩情。君主带头行礼，庶民亦然。\\n\\n此章于今人的启示在于：许多古礼背后有其精神，这种精神需要传承，若无人学习、无人思考其所以然，疑惑便始终存在，礼一旦失传就真的失传了。子张乃贵族后裔，受过良好教育，仍不解三年之丧，其发问之意只在担心国家无人治理，尚未领会孔子为政的基础。孔子强调为政以德，而非以术、以智、以权谋；德行何来？该干什么便干什么。父亲安排好班子，继位者承其道路，再为子孙安排好班子，家、国、天下皆循此理，一代一代传承，便一代一代兴旺。", keyPoint: "为政、孝道、学习、教育" },
  { id: 488, chapterId: 14, order: 41, original: "子曰：“上好礼，则民易使也。”", translation: "孔子说:“居上位的人遇事依礼而行,民众就容易役使了。”", commentary: "①好礼：好，喜好、崇尚；礼，礼法、制度规范。指在上位者崇尚礼法、按礼行事。\\n②上：在上位的人，即统治者、领导者。居上位者负有率先守礼的道德义务。\\n③民易使：民众容易役使、乐于听从差遣。使，役使、差遣。\\n④本章与上章\"高宗谅阴，三年不言\"紧相承接：上章言居丧守礼，本章申说在上者好礼则民易治之理。\\n⑤北辰：北极星。\"为政以德，譬如北辰，居其所而众星拱之\"，喻在上者以德为则，众人自然归附。\\n---\\n\\n【解读】本章紧承上章\"高宗谅阴，三年不言\"而来，以\"上好礼，则民易使也\"进一步申说为政之道。上章言在上位者居丧三年、不问政事，文武百官各司其职，天下照常运转；本章则点出其中关键——上位者以礼自律、以身作则，则民众自然乐于听从驱使。孔子一贯的政治理想，正是主张为政者先奉行道德、遵纪守法，以仁政与礼制立身作则，天下之人随之效法。为政篇\"为政以德，譬如北辰，居其所而众星拱之\"、八佾篇之正反事例，讲的都是同一道理。若在上者带头破坏规矩，上行下效，则犯上作乱、违礼之事便随之滋生。\\n\\n儒家对在上位者要求尤严。古代世袭制度下，贵族生而有位，也就生而有道德义务：率先奉行礼法，教化子民，教人稼穑养生、御敌卫国，这是从上到下的礼之规则。今人回望古代，常以阶级压迫视贵族，然就当时而言，礼更强调的是血脉带来的责任与担当。时移世易，具体礼仪自当随时代演进，不可盲目复古，然\"领导以身作则\"这一精神则具永恒价值。\\n\\n其理甚简：身为领导定下规矩，率先维护遵行，下位者自然尊重规则；人人讲规矩，又有什么不易驱使的呢？家庭亦然——家长带头违犯家规，却指望孩子做好，断无可能；家长以身作则，孩子自会轻松追随。由家庭而社会，无论处在哪个位置，在上也好、为民也罢，都当按礼法行事。下位之人亦有本分，唯以上位者为学习榜样；而人人皆在成长，终将从下位走向上位，届时更须以身作则。今人讲道德、讲政治、讲法律，循社会主义核心价值观与为人民服务之宗旨而行，许多事情自然水到渠成。本章最大的启示在于：与其费心琢磨如何约束手下、引导孩子，不如把心思放在\"好礼\"之上——以礼修身、以礼作则，则上行下效，事半功倍。", keyPoint: "为政、仁德、孝道、教育、礼乐" },
  { id: 489, chapterId: 14, order: 42, original: "子路问君子，子曰：“修己以敬。”曰：“如斯而已乎？”曰：“修己以安人。”曰：“如斯而已乎？”曰：“修己以安百姓。修己以安百姓，尧、舜其犹病诸！”", translation: "子路问怎样做才是君子。孔子说：“修养自己以做到恭敬认真。”子路说：“像这样就可以了吗？”孔子说：“修养自己并且使别人安乐。”子路又问：“像这样就可以了吗？”孔子说：“修养自己并且使百姓安乐。修养自己，使百姓都安乐，尧、舜大概都担心很难完全做到吧！”", commentary: "①修己：修养自身，修养自己的品德与学识。\\n②敬：恭谦庄重、凡事认真，对道对仁不马虎。敬既是修己的出发点，又是修己的归宿。\\n③安人：使人安定。此处\"人\"取狭义，指身边的亲人朋友，即齐家。\\n④安百姓：使天下百姓皆得安宁，即治国、平天下。\\n⑤病：为难、担忧、忧虑。\"尧、舜其犹病诸\"，谓安百姓之事连尧舜都难以完全做到。\\n---\\n\\n【解读】本章记子路问君子，孔子以\"修己以敬\"答之，又经子路再三追问，层层展开为\"修己以安人\"\"修己以安百姓\"。在孔子看来，君子既是执政者，又是有德之人，而其成功的要领唯在修己。若子路能如颜回之闻一以知十、子贡之举一隅以三隅反，闻\"修己以敬\"四字便已足够；正因其信不过、一再追问，孔子才得以将道理讲透，恰是启发教学的契机。\\n\\n\"敬\"之一字最堪玩味。敬即恭谦、庄重、威严，凡事认真，对道对仁不马虎；它既是修己的出发点，又是修己的归宿。以敬修己，同时以敬为修己的目标，内外一如，这正是曾子所传\"夫子之道，忠恕而已\"——对人事忠贞不二，以待己之心待人。自己修养到位，身边的人自然安定，此即齐家；进而使天下百姓皆得安宁，此即治国、平天下。可见平天下、治国、齐家皆包含于修身之中，一切不离自身、不离自心。\\n\\n孔子最后说\"修己以安百姓，尧、舜其犹病诸\"，意谓如此境界连尧舜也未能完全做到，足够人用一生去践行。\"病\"字是说尧舜尚且以此为难，并非贬低，而是极言安百姓之道的广大深远。子路之屡问或为明知故问，正是借对话让后学明瞭：修身、安人、安百姓是一个自然统一的过程，绝非彼此割裂的三件事——自己做好了，身边的人自然也好，百姓自然也能得安宁。\\n\\n本章对今人的启示，与前几章一贯：时刻知道自己的本分，如\"君子思不出其位\"，本分就是修己以敬、修己以安人、修己以安百姓。学无止境，然其方向不是向外驰求、一上来便想着平定天下，而是向内修己。这与佛家、道家眼光向内的修为方式相通，亦与基督教\"欲除别人眼中之刺，先除自己眼中梁木\"之教相合。把修己这一根本做好，则一切皆有着落。", keyPoint: "为政、修身、教育、齐家" },
  { id: 490, chapterId: 14, order: 43, original: "原壤夷俟，子曰：“幼而不孙弟，长而无述焉，老而不死，是为贼！”以杖叩其胫。", translation: "原壤叉开两条腿坐着等孔子。孔子说：“你小时候不谦恭不敬兄长，长大了没有什么值得称道的，老了还不死掉，真是个害人的家伙。”说完，用手杖敲击他的小腿。", commentary: "①原壤：孔子的老朋友。据《孔子家语》，其母去世时孔子曾助其治丧，然其生性洒脱、不守礼法。\\n②夷俟：夷，两腿岔开而坐，古人以跪坐为正，此为失礼之态；俟，等待。指岔开双腿坐地以待孔子。\\n③孙弟：通\"逊悌\"，逊顺恭敬、敬爱兄长。幼而不孙弟，谓少时便不逊顺、不敬长辈。\\n④无述：无可称述，一生没有可说的成就。\\n⑤贼：害人虫、祸害。以杖叩其胫，用手杖敲击其小腿，促其收腿守礼。\\n---\\n\\n【解读】整部《论语》中，孔子素以温、良、恭、俭、让示人，罕见动怒；本章却记其不仅发火，更以杖叩原壤之胫，极为独特。据《孔子家语》，原壤乃孔子故友，其母去世时孔子还曾助其治丧，然其人性格洒脱、不守礼法，母丧期间犹自唱歌，俨然道家隐士风范。孔子正是以其为反面教材，垂训弟子。\\n\\n\"原壤夷俟\"四字状其无礼之态：夷为两腿岔开而坐，古人以跪坐为正，岔坐已是失礼，何况见孔子来而不起身致敬。孔子历数其三桩不是：幼而不孙弟——少时便不逊顺、不敬长辈，不守规矩；长而无述焉——年长而一事无成，无可称述；老而不死，是为贼——老而不修养善行，徒然苟活，使人产生\"不做好事也能长寿\"的误认，实为害人虫。杖叩其胫，非出于盛怒，乃促其收回伸出的双腿、坐姿合礼，是规劝改正的善意。\\n\\n解读本章须回到具体历史情境。原壤与孔子为同乡故交，宗族相亲，孔子待亲近之人从不客气——所谓\"亲不失其亲，旧不失其旧\"，正因为是朋友，才不容其倚老卖老、放肆无礼，且恐他人效仿，故必当面纠正。这同时也说明：纵有圣人在侧，若不自加修为、不向圣人学习，到头来仍不免落得\"老而不死是为贼\"的感叹，白白辜负机缘。\\n\\n原壤或许是故意与孔子配合演出，但更应看到本章是一面镜子：孔子之杖，仿佛也敲在每一位读者的腿上。年幼时是否谦逊敬长，年长后有无可称述的成就，老来能否善终，皆当反躬自省。照见反面而正向而行，正是本章给今人最大的启示。", keyPoint: "孝道、教育、礼乐、齐家" },
  { id: 491, chapterId: 14, order: 44, original: "阙党童子将命，或问之曰：“益者与？”子曰：“吾见其居于位也，见其与先生并行也。非求益者也，欲速成者也。”", translation: "阚党的一个童子来传信息。有人问孔子：“这是一个求进益的人吗？”孔子说：“我看见他坐在成人的席位上，看见他和长辈并肩而行。他不是个求进益的人，而是一个急于求成的人。”", commentary: "①阙党：地名，在鲁国，一说在孔子家乡附近，一说在孔子晚年隐居地附近。\\n②童子：未成年之人，未行冠礼、不到二十岁。\\n③将命：传达使命。将，执持、奉持；命，使命、命令。\\n④益：增益、进益，学问修养有所增进。益者，求上进的人。\\n⑤居位：坐在成人的席位上；与先生并行，与年长者并肩而行。古礼后生当行于长者之后，以示谦逊。\\n---\\n\\n【解读】本章为宪问第十四之收尾，意味深长。阙党一童子替孔子传达使命，有人问其是否求上进之人，孔子的回答却出人意表：此童非求益者，乃欲速成者。表面看似对童子的否定，细究之下，实是孔子教育思想的精微呈现。\\n\\n先看孔子何以如此判断。童子未行冠礼，尚不足二十岁，本应谦逊守礼；而孔子所见有二：其一，\"居其位\"，大模大样坐在成人席位上；其二，\"与先生并行\"，与年长者并肩而行。古代礼制，后生与长者同行当行于其后，以示谦逊，除非为长者开道，否则并肩即是失礼。此二端足见其心气高傲、急于求成。\\n\\n然孔子安排此童传命，正因其\"欲速成\"而非因其已做得完美。心气高者，恰需在具体事务中磨炼，让他通过一次次传命办事，慢慢明白自己该居何位、行何礼。这与常人的理解恰成对照：一般人以为童蒙获孔子任用，必是表现优秀、受其赏识；孔子之意却是因其不足而予之锻炼机会。圣人之教，不是挑剔指责，更不打击其进取心，而是循循善诱，托付职责使其在事上成长——童子的求学愿望与上进动力，孔子分明是珍视的。\\n\\n由此推开，本章实有数层启示。就个人修养言，当知本分：不居其位而居其位、与先生并行，皆非求进之道，急于求成反易一事无成；以礼行事、守规矩，才是通向智慧、仁德、勇气的阳光大道。就教育言，当学孔子因材施教、事上磨炼之法。就吾辈言，人人皆是童子——许多事不知该如何做，正需圣贤指引，从领命、传道处学起，不断努力，永不失进取之心与赤子之心。如此理解，方见本章收束全篇的分量。", keyPoint: "教育" }
];
